/* Underhive Korea tutorial curriculum. Exercises use imaginary records and never mutate saved gangs. */
(function(){
'use strict';
const lessons=[{"id":"workspace-basics","category":"app","editions":["n23","n26"],"title":{"ko":"앱 시작과 기록 보호","en":"Your workspace and safe records"},"summary":{"ko":"화면 이동, 판본, 검색, 계정 저장과 백업을 익힙니다.","en":"Learn navigation, editions, searching, account storage, and backups."},"minutes":12,"references":[],"steps":[{"id":"orientation","title":{"ko":"작업 공간 살펴보기","en":"Find your way around"},"body":{"ko":"홈은 갱과 캠페인을 여는 출발점입니다. 갱은 파이터와 장비를 관리하고, 캠페인은 참가자·영토·전투를 묶습니다. 이 튜토리얼의 문제는 가상 상황만 사용하며 실제 기록을 만들거나 바꾸지 않습니다.","en":"Home opens your gangs and campaigns. A gang contains fighters and equipment; a campaign connects participants, territories, and battles. These tutorial exercises use imaginary situations and never create or change your records."},"bullets":[{"ko":"갱을 열면 해당 갱의 파이터 명단과 보관고를 확인할 수 있습니다.","en":"Open a gang to inspect its fighter roster and stash."},{"ko":"캠페인을 열면 참가 갱과 전투 기록을 확인할 수 있습니다.","en":"Open a campaign to inspect participating gangs and battle records."},{"ko":"메뉴의 계정 화면에서 연결·저장 상태를 확인하세요.","en":"Use Account in the menu to check connection and save status."}],"references":[]},{"id":"edition","title":{"ko":"먼저 판본 정하기","en":"Choose the edition first"},"body":{"ko":"갱이나 캠페인을 만들 때 N23 또는 N26을 선택합니다. 같은 이름의 스킬이나 장비도 판본에 따라 효과와 비용이 다를 수 있습니다. 화면의 판본 표시를 확인하고 서로 다른 판본의 수치를 섞지 마세요.","en":"Select N23 or N26 when creating a gang or campaign. Identically named skills and equipment can have different effects and costs between editions. Check edition badges before using a rule or a catalog item."},"bullets":[{"ko":"앱 사용법 수업은 두 판본에 공통으로 적용됩니다.","en":"App workflow lessons apply to both editions."},{"ko":"전투 규칙 수업은 N26으로 표시된 경우에만 N26 규칙을 가르칩니다.","en":"Battle lessons marked N26 teach only N26 rules."},{"ko":"학습 화면에서 판본을 바꾸면 해당 판본의 수업과 자료만 선택하세요.","en":"After changing the learning edition, use lessons and references for that edition."}],"references":[]},{"id":"language-search","title":{"ko":"언어 전환과 검색","en":"Switch languages and search"},"body":{"ko":"상단의 한 / EN으로 표시 언어를 바꿀 수 있습니다. 고유명사는 한국어에서 음차로 표시됩니다. 저장된 갱 이름과 개인 메모는 직접 작성한 내용이 유지되므로 번역 전후에도 자신의 기록을 확인할 수 있습니다.","en":"Use 한 / EN at the top to change display language. Game proper names use phonetic Korean forms. Your written gang names and private notes retain their original text, so you can recognize your records in either language."},"bullets":[{"ko":"장비·스킬 선택창에서는 영어 이름 또는 한국어 음차로 검색해 보세요.","en":"Try English names or their Korean phonetic forms in equipment and skill pickers."},{"ko":"이름이 비슷하면 판본·무기 프로필·비용까지 확인하세요.","en":"For similar names, compare edition, weapon profile, and cost."}],"references":[],"exercise":{"type":"choice","prompt":{"ko":"N23 갱에 쓸 장비를 찾고 있습니다. 무엇을 먼저 확인해야 할까요?","en":"You are finding equipment for an N23 gang. What should you check first?"},"options":[{"id":"1","text":{"ko":"N23 장비인지 확인한다.","en":"Check that it belongs to N23."}},{"id":"2","text":{"ko":"이름이 같으면 N26 장비를 사용한다.","en":"Use the N26 item if its name matches."}},{"id":"3","text":{"ko":"번역된 이름만 같으면 판본은 무시한다.","en":"Ignore edition if the translated names match."}}],"correctOption":"1","explanation":{"ko":"같은 이름도 판본별 항목이 따로 있습니다. 갱과 같은 판본의 항목을 선택해야 다른 규칙과 비용이 섞이지 않습니다.","en":"Names can be shared across separate edition entries. Select the gang’s edition to keep its rules and costs consistent."}}},{"id":"storage","title":{"ko":"저장 상태 이해하기","en":"Understand saving"},"body":{"ko":"이 브라우저의 기록과 계정에 연결된 온라인 기록을 구분하세요. 계정 연결이나 동기화가 진행 중이면 완료 상태를 확인한 뒤 다른 기기로 이동하는 것이 좋습니다. 연결 오류가 표시되면 계정 화면의 안내에 따라 다시 연결하거나 동기화하세요.","en":"Distinguish records in this browser from online records linked to your account. If connection or synchronization is running, confirm completion before moving to another device. When an error appears, use the account screen to reconnect or synchronize."},"bullets":[{"ko":"서로 다른 기기에서 같은 기록을 동시에 수정하면 충돌 선택창이 나타날 수 있습니다.","en":"Editing the same record on multiple devices can produce a conflict choice."},{"ko":"충돌 시 어느 쪽이 최신인지 확인하고 보관할 기록을 선택하세요.","en":"Inspect which copy contains the desired changes before choosing a version."},{"ko":"로그인한 계정이 맞는지도 확인하세요.","en":"Also check that you are using the intended account."}],"references":[]},{"id":"backup","title":{"ko":"백업과 복원의 차이","en":"Back up before replacing records"},"body":{"ko":"데이터 관리의 JSON 내보내기는 현재 기록을 파일로 보관하는 방법입니다. 가져오기는 파일 내용을 적용하는 작업이므로 확인창을 읽고 기존 기록을 먼저 백업하세요. 예시 초기화·삭제 같은 기능은 연습용 기록에서 사용해야 합니다.","en":"JSON export in Data Management saves a copy of your records as a file. Import applies a file’s contents, so read the confirmation and export your existing records first. Use sample reset and deletion features only when you intend to replace those records."},"bullets":[{"ko":"파일 이름에 날짜를 붙이면 여러 백업을 구별하기 쉽습니다.","en":"Date your backup filenames to distinguish different copies."},{"ko":"다른 기기에 옮기기 전에는 파일이 실제로 다운로드됐는지 확인하세요.","en":"Check that the backup file downloaded before changing devices."},{"ko":"갱을 삭제하는 작업은 전투 중 OOA 상태를 표시하는 것과 다릅니다.","en":"Deleting a gang is different from marking a fighter Out of Action in a battle."}],"references":[]},{"id":"checkpoint","title":{"ko":"기록을 지키는 연습","en":"Practice protecting your records"},"body":{"ko":"새 휴대전화로 옮기려는데 계정 연결 상태가 불확실하고 현재 브라우저에 중요한 갱이 있습니다. 먼저 안전한 사본을 확보하고 연결 상태를 확인하는 순서를 선택하세요. 이 문제에서는 실제 내보내기나 가져오기를 실행하지 않습니다.","en":"You are moving to a new phone, but account connection is uncertain and this browser contains an important gang. Choose a sequence that preserves a copy before resolving the connection. This exercise does not actually export or import anything."},"bullets":[{"ko":"학습 진도와 실제 갱 기록은 별도로 취급됩니다.","en":"Learning progress is separate from your real gang records."},{"ko":"진도를 초기화해도 갱·파이터·캠페인은 바뀌지 않습니다.","en":"Restarting a lesson does not change gangs, fighters, or campaigns."}],"references":[],"exercise":{"type":"choice","prompt":{"ko":"가장 적절한 이동 순서는 무엇일까요?","en":"Which transfer sequence is most appropriate?"},"options":[{"id":"1","text":{"ko":"현재 기록 백업 → 계정 연결·저장 상태 확인 → 새 기기에서 확인","en":"Back up current records → verify account connection and saving → check the new device"}},{"id":"2","text":{"ko":"브라우저 데이터 삭제 → 나중에 백업","en":"Delete browser data → make a backup later"}},{"id":"3","text":{"ko":"새 기기에서 예시 초기화 → 현재 기록 자동 복구 기대","en":"Reset samples on the new device → expect current records to return automatically"}}],"correctOption":"1","explanation":{"ko":"먼저 사본을 확보하면 연결 문제나 잘못된 복원 선택에 대비할 수 있습니다. 저장 상태를 확인한 뒤 새 기기의 내용을 비교하세요.","en":"A backup preserves a copy before connection or restore choices. Verify saving, then compare the records shown on the new device."}}}]},{"id":"online-campaign","category":"app","editions":["n23","n26"],"title":{"ko":"온라인 캠페인 모집과 참가","en":"Recruit and join an online campaign"},"summary":{"ko":"주최자와 참가자의 흐름, 승인, 판본 일치, 명단 동기화를 배웁니다.","en":"Learn host and participant workflows, approval, matching editions, and roster synchronization."},"minutes":15,"references":[],"steps":[{"id":"host-create","title":{"ko":"주최자: 캠페인 준비","en":"Host: prepare the campaign"},"body":{"ko":"캠페인 목록에서 캠페인을 만들고 이름·판본·설명을 정합니다. 계정 연결과 저장 상태를 확인한 뒤 캠페인을 열어 온라인 참가 버튼을 누르세요. 캠페인 소유자가 모집 설정과 신청 승인을 관리합니다.","en":"Create a campaign from the campaign list and choose its name, edition, and description. Confirm account connection and saving, open the campaign, and choose Online Participation. The owner manages recruitment settings and application approval."},"bullets":[{"ko":"모집 안내에는 플레이 일정, 허용 갱, 캠페인 규칙, 연락 방법을 적으면 좋습니다.","en":"Useful recruitment information includes schedule, allowed gangs, campaign rules, and contact details."},{"ko":"갱과 캠페인은 같은 판본이어야 온라인 참가가 가능합니다.","en":"A joining gang must use the campaign’s edition."}],"references":[]},{"id":"host-publish","title":{"ko":"주최자: 모집 켜고 링크 공유","en":"Host: enable recruitment and share the link"},"body":{"ko":"온라인 참가에서 참가 신청 받기를 켜고 정원과 공개 안내를 저장합니다. 표시된 모집 링크를 복사해 참가자에게 전달하세요. 링크를 열 수 있어도 자동으로 참가 승인이 되지는 않습니다.","en":"Enable join requests in Online Participation, set the player limit and public description, and save. Copy the recruitment link and share it with participants. Opening the link does not automatically approve a player."},"bullets":[{"ko":"공개 화면에는 캠페인 이름·판본·주최자·모집 안내·참가 인원이 표시됩니다.","en":"The public page shows campaign name, edition, host, recruitment description, and player count."},{"ko":"모집을 중지하면 새 신청을 받지 않습니다.","en":"Pausing recruitment stops new applications."},{"ko":"링크 교체는 기존 주소를 무효화하지만 이미 접수된 신청은 유지합니다.","en":"Replacing the link invalidates its old address while keeping existing applications."}],"references":[]},{"id":"participant-apply","title":{"ko":"참가자: 내 갱으로 신청","en":"Participant: apply with your gang"},"body":{"ko":"모집 링크를 연 뒤 ChatGPT로 로그인하고 계정 연결을 확인합니다. 같은 판본의 본인 갱을 골라 메시지를 적고 신청을 보냅니다. 갱이 보이지 않으면 자신의 갱인지, 판본이 같은지, 계정에 저장됐는지 확인하세요.","en":"Open the recruitment link, sign in with ChatGPT, and confirm account connection. Select your own gang in the matching edition, optionally write a message, and send the request. If no gang appears, check ownership, edition, and account saving."},"bullets":[{"ko":"다른 사람의 읽기 전용 갱으로는 신청할 수 없습니다.","en":"You cannot apply with someone else’s read-only gang."},{"ko":"승인 대기 중 갱 내용을 바꿨다면 신청을 취소하고 다시 신청하세요.","en":"If you change your gang while waiting, withdraw and apply again."}],"references":[],"exercise":{"type":"choice","prompt":{"ko":"N26 캠페인의 모집 링크에서 내 N23 갱이 보이지 않습니다. 어떻게 해야 할까요?","en":"Your N23 gang is absent from an N26 recruitment form. What should you do?"},"options":[{"id":"1","text":{"ko":"캠페인 판본을 확인하고 같은 판본의 본인 갱을 준비한다.","en":"Check the campaign edition and prepare your own gang in that edition."}},{"id":"2","text":{"ko":"갱 이름에 N26이라고 적어서 신청한다.","en":"Add N26 to the gang’s name and apply."}},{"id":"3","text":{"ko":"다른 참가자의 읽기 전용 갱으로 신청한다.","en":"Apply with another participant’s read-only gang."}}],"correctOption":"1","explanation":{"ko":"판본은 이름이 아니라 갱의 설정으로 검사됩니다. 같은 판본의 본인 갱을 계정에 저장한 뒤 목록을 새로고침하세요.","en":"Edition is checked from the gang’s settings, not its name. Save your own matching-edition gang to your account, then refresh the list."}}},{"id":"host-approve","title":{"ko":"주최자: 신청 검토와 승인","en":"Host: review and approve"},"body":{"ko":"온라인 참가의 신청 목록에서 플레이어와 갱, 메시지를 확인하고 승인 또는 거절을 선택합니다. 승인은 참가 갱을 캠페인에 연결하고 참가자에게 캠페인 열람 권한을 부여합니다. 신청이 대기 중인 것과 승인된 것은 서로 다른 상태입니다.","en":"Review the player, gang, and message in the application list, then approve or reject. Approval connects the gang to the campaign and grants the participant access to view it. Pending and approved are separate states."},"bullets":[{"ko":"정원이 가득 찼거나 모집이 중지되면 새 참가가 제한됩니다.","en":"Capacity and paused recruitment can restrict new participation."},{"ko":"승인 후 참가자는 모집 화면에서 캠페인 열기로 이동할 수 있습니다.","en":"After approval, the participant can choose Open campaign from the recruitment page."},{"ko":"캠페인 열람 권한이 모든 운영 기능의 수정 권한을 뜻하지는 않습니다.","en":"Viewing a campaign does not grant permission to edit every management function."}],"references":[]},{"id":"sync-roster","title":{"ko":"승인 후 명단 갱신","en":"Keep an approved roster current"},"body":{"ko":"참가자는 자신의 원본 갱을 수정하고 계정 저장 상태를 확인합니다. 승인된 온라인 명단은 원본 갱의 변경을 반영합니다. 다른 참가자의 갱을 자신의 기록처럼 수정하지 말고 소유자에게 변경을 요청하세요.","en":"Edit your own original gang and verify account saving. Its changes are reflected in the approved online roster. Ask the owner to make changes to another participant’s gang rather than treating that roster as your own."},"bullets":[{"ko":"갱의 개인 메모는 온라인 참가 명단 공유에서 제외됩니다.","en":"Private gang notes are excluded from online enrollment roster sharing."},{"ko":"공개 모집 설명과 참가 신청 메시지는 다른 사람에게 보이는 내용입니다.","en":"Recruitment descriptions and application messages are visible to other people."},{"ko":"동기화 오류가 표시되면 계정 상태와 판본을 확인한 뒤 다시 저장하세요.","en":"If synchronization reports an error, check account status and edition, then save again."}],"references":[]},{"id":"join-checkpoint","title":{"ko":"참가 상태 확인 연습","en":"Practice checking participation"},"body":{"ko":"신청 버튼을 누른 직후에는 주최자의 승인이 필요합니다. 대기 중에는 상태 새로고침으로 처리 결과를 확인할 수 있고, 참가 의사가 바뀌면 신청 취소를 선택할 수 있습니다. 주최자는 모집 설정과 신청 목록을 구분해 관리하세요.","en":"After submission, the host must approve the request. While waiting, refresh the status to check its outcome, or withdraw if you no longer wish to join. Hosts manage recruitment settings separately from individual applications."},"bullets":[{"ko":"모집 링크를 공유하는 작업과 실제 승인 작업은 구분됩니다.","en":"Sharing a recruitment link and approving a request are separate actions."},{"ko":"이 수업의 선택은 실제 신청이나 승인을 보내지 않습니다.","en":"Choices in this lesson do not send real requests or approvals."}],"references":[],"exercise":{"type":"choice","prompt":{"ko":"참가자가 신청을 보냈고 상태가 승인 대기입니다. 다음 단계는?","en":"A participant submitted a request and it is Pending approval. What comes next?"},"options":[{"id":"1","text":{"ko":"참가자가 캠페인 운영자 권한을 자동으로 얻는다.","en":"The participant automatically becomes an administrator."}},{"id":"2","text":{"ko":"주최자가 신청을 검토해 승인하고 참가자는 상태를 확인한다.","en":"The host reviews and approves the request; the participant checks the status."}},{"id":"3","text":{"ko":"링크를 다시 복사하면 승인된다.","en":"Copying the recruitment link again approves it."}}],"correctOption":"2","explanation":{"ko":"신청 제출과 승인은 별개입니다. 주최자가 승인해야 갱이 캠페인에 연결되고 참가자가 공유 캠페인을 열 수 있습니다.","en":"Submission and approval are distinct. The host must approve before the gang is connected and the participant can open the shared campaign."}}}]},{"id":"gang-foundations","category":"campaign","editions":["n26"],"title":{"ko":"N26 갱 창설과 장비 구성","en":"N26 gang creation and equipment"},"summary":{"ko":"창설 예산, 역할 비율, 파이터 카드, 무기 슬롯과 장비 세트를 구성합니다.","en":"Build a roster using creation budget, role ratios, fighter cards, weapon slots, and equipment sets."},"minutes":18,"references":[{"kind":"coreRules","id":"n26-core-gang-budget","edition":"n26"},{"kind":"coreRules","id":"n26-core-gang-composition","edition":"n26"},{"kind":"coreRules","id":"n26-core-type-semantics","edition":"n26"},{"kind":"coreRules","id":"n26-core-roster-fields","edition":"n26"},{"kind":"coreRules","id":"n26-core-advancement-timing","edition":"n26"},{"kind":"coreRules","id":"n26-core-weapon-profile-card","edition":"n26"},{"kind":"coreRules","id":"n26-core-weapon-slots","edition":"n26"},{"kind":"coreRules","id":"n26-core-loadouts","edition":"n26"},{"kind":"coreRules","id":"n26-core-gang-finances","edition":"n26"}],"steps":[{"id":"budget","title":{"ko":"예산부터 배분하기","en":"Start with the budget"},"body":{"ko":"N26의 기본 창설 예산은 1000크레딧입니다. 파이터와 장비의 합계가 예산을 넘지 않도록 역할별 지출을 계획하세요. 캠페인에서는 남은 크레딧을 보관하지만 스커미시에서는 창설 잔액이 소멸합니다. 아비트레이터가 정한 캠페인 예산이 있으면 그것을 적용합니다.","en":"N26 uses a default creation budget of 1000 credits. Plan fighter and equipment spending so the total stays within that budget. Campaign gangs keep unused credits; skirmish creation loses the remainder. Apply a different campaign budget when the arbitrator sets one."},"bullets":[{"ko":"앱에서 새 갱을 만들 때 N26과 원하는 갱 유형을 선택하세요.","en":"Select N26 and the intended gang type when creating the gang."},{"ko":"모집비·장비비·남길 크레딧을 각각 확인하세요.","en":"Track recruitment costs, equipment costs, and remaining credits separately."}],"references":[{"kind":"coreRules","id":"n26-core-gang-budget","edition":"n26"}]},{"id":"composition","title":{"ko":"리더와 갱 구성 비율","en":"Check the roster composition"},"body":{"ko":"기본 갱은 리더가 정확히 한 명 필요합니다. 챔피언·브루트·행어온의 합은 그 밖의 모델 수를 넘을 수 없습니다. 펫은 장비로 취급하여 이 비율에서 제외하고, 갱별 명시적 예외가 있으면 함께 확인합니다.","en":"A standard gang requires exactly one Leader. The combined number of Champions, Brutes, and Hangers-on cannot exceed the other models. Pets are equipment and are excluded from this ratio. Check any explicit exception for the chosen gang."},"bullets":[{"ko":"이름에 리더라고 적는 것만으로 리더 하위유형이 생기지는 않습니다.","en":"Writing Leader in a name does not grant the Leader subtype."},{"ko":"모집 목록의 유형과 하위유형을 실제 규칙 적용 기준으로 확인하세요.","en":"Use the actual type and subtype fields when applying roster rules."}],"references":[{"kind":"coreRules","id":"n26-core-gang-composition","edition":"n26"},{"kind":"coreRules","id":"n26-core-type-semantics","edition":"n26"}]},{"id":"recruit","title":{"ko":"파이터를 선택해 모집하기","en":"Recruit from the correct fighter list"},"body":{"ko":"갱의 파이터 추가에서 해당 판본·갱에 맞는 유형을 고르고 이름, 비용, 시작 XP, 능력치를 확인합니다. 특수규칙은 유형·하위유형·장비에서 올 수 있으므로 이름만 보고 유추하지 마세요. 시작 XP는 N26에서 새로 얻는 성장으로 처리하지 않습니다.","en":"Use Add Fighter in the gang and choose a type for its edition and gang. Check name, cost, starting XP, and characteristics. Special rules can come from type, subtype, or equipment; do not infer them only from a name. Starting XP does not itself grant N26 advancements."},"bullets":[{"ko":"모집 후 카드의 실제 능력치와 기본 장비를 확인하세요.","en":"After recruitment, inspect the actual characteristics and default equipment."},{"ko":"직접 입력한 커스텀 유형은 선택한 데이터의 정확성을 스스로 확인해야 합니다.","en":"For custom types, verify the data you enter."}],"references":[{"kind":"coreRules","id":"n26-core-roster-fields","edition":"n26"},{"kind":"coreRules","id":"n26-core-advancement-timing","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"챔피언·브루트·행어온이 합계 4명이고 나머지 모델이 3명입니다. 펫 2마리를 추가하면 기본 구성 제한을 만족할까요?","en":"There are 4 Champions/Brutes/Hangers-on combined and 3 other models. Do 2 additional Pets satisfy the standard ratio?"},"options":[{"id":"1","text":{"ko":"예. 펫도 다른 모델 수에 넣는다.","en":"Yes. Pets count as other models."}},{"id":"2","text":{"ko":"아니요. 펫은 비율에서 제외되어 4가 3을 넘는다.","en":"No. Pets are excluded, so 4 still exceeds 3."}},{"id":"3","text":{"ko":"리더가 있으면 비율 제한은 없다.","en":"The ratio never applies when a Leader is present."}}],"correctOption":"2","explanation":{"ko":"펫은 이 구성 비율의 모델 수를 늘리지 않습니다. 갱별 예외가 없다면 제한 대상 합계가 다른 모델 수 이하가 되도록 명단을 조정해야 합니다.","en":"Pets do not increase the model count for this ratio. Without a gang-specific exception, adjust the roster so the restricted total does not exceed the other models."}}},{"id":"profiles","title":{"ko":"무기 프로필과 슬롯 읽기","en":"Read weapon profiles and slots"},"body":{"ko":"N26 무기 카드에서는 사거리, S, AP, L, 특성을 따로 읽습니다. L은 W가 0에 도달했을 때의 부상 주사위 수이며 이전 판본의 대미지와 같은 값으로 사용하지 않습니다. 전투원은 기본적으로 무기 슬롯 3개를 사용하고 별표 무기는 2칸을 차지합니다.","en":"Read range, S, AP, L, and traits separately on an N26 weapon card. L determines injury dice when W reaches zero; it is not a legacy Damage value. A fighter normally has 3 weapon slots, and a starred weapon uses 2 slots."},"bullets":[{"ko":"그레네이드는 무기 슬롯 수에서 제외합니다.","en":"Grenades do not consume weapon slots."},{"ko":"무기 액세서리는 각 무기당 최대 1개입니다.","en":"Each weapon allows at most 1 accessory."},{"ko":"차량은 개별 항목의 무기 제한을 확인하세요.","en":"Vehicles use the weapon limits in their own entries."}],"references":[{"kind":"coreRules","id":"n26-core-weapon-profile-card","edition":"n26"},{"kind":"coreRules","id":"n26-core-weapon-slots","edition":"n26"}]},{"id":"sets-finances","title":{"ko":"장비 세트·레이팅·자산","en":"Distinguish equipment sets, Rating, and Wealth"},"body":{"ko":"여러 장비 세트가 있어도 파이터는 명부에 한 번만 기록됩니다. 같은 아이템을 여러 세트가 공유해도 구매와 가치는 한 번만 계산하고 전투에서는 세트 하나를 사용합니다. 레이팅은 모델 가치 합계, 자산은 여기에 잔액과 보관고 장비 가치를 더한 값입니다.","en":"A fighter remains one roster entry even with multiple equipment sets. A shared item is purchased and valued once, and one set is used in a battle. Rating totals model values; Wealth also includes unspent credits and stash equipment values."},"bullets":[{"ko":"XP·성장·지속 부상은 같은 모델의 모든 카드에 공유됩니다.","en":"XP, advancements, and lasting injuries are shared across that model’s cards."},{"ko":"장비 세트를 새 모델로 복제해서 비용이나 전투 참여를 중복하지 마세요.","en":"Do not duplicate a set as a new model for extra value or battle participation."},{"ko":"무작위 크루의 장비 세트 선택은 캠페인에서 정한 절차를 확인하세요.","en":"Check the campaign procedure for equipment sets in random crew selection."}],"references":[{"kind":"coreRules","id":"n26-core-loadouts","edition":"n26"},{"kind":"coreRules","id":"n26-core-gang-finances","edition":"n26"}]},{"id":"budget-practice","title":{"ko":"가상 창설 정산","en":"Practice a creation ledger"},"body":{"ko":"연습 갱은 파이터 비용에 650크레딧, 장비에 280크레딧을 썼습니다. 기본 예산으로 캠페인 갱을 만들었다고 가정합니다. 합계와 잔액을 계산하고, 실제 갱을 저장하기 전 구성 비율과 장비 슬롯까지 별도로 점검하세요.","en":"An imaginary gang spends 650 credits on fighters and 280 on equipment. Assume the default campaign creation budget. Calculate the total and remainder, then remember to check composition and weapon slots separately before saving a real gang."},"bullets":[{"ko":"예산이 맞아도 갱별 구성과 장비 접근 제한은 따로 적용됩니다.","en":"Meeting the budget does not remove gang composition or equipment access restrictions."},{"ko":"캠페인 예산이 수정된 경우 기본 1000 대신 정해진 예산으로 다시 계산합니다.","en":"If the campaign changes its budget, calculate using that value rather than the default 1000."}],"references":[{"kind":"coreRules","id":"n26-core-gang-budget","edition":"n26"},{"kind":"coreRules","id":"n26-core-gang-composition","edition":"n26"},{"kind":"coreRules","id":"n26-core-weapon-slots","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"이 연습 갱의 사용액과 캠페인 잔액은?","en":"What are the spent credits and campaign remainder?"},"options":[{"id":"1","text":{"ko":"930 사용, 70 보관","en":"930 spent, 70 retained"}},{"id":"2","text":{"ko":"930 사용, 70 반드시 소멸","en":"930 spent, 70 necessarily lost"}},{"id":"3","text":{"ko":"1000 사용, 장비비는 제외","en":"1000 spent, equipment ignored"}}],"correctOption":"1","explanation":{"ko":"650 + 280 = 930, 1000 − 930 = 70입니다. 캠페인의 창설 잔액은 보관하며 스커미시의 잔액 소멸과 구분합니다.","en":"650 + 280 = 930; 1000 − 930 = 70. Campaign creation retains the remainder; distinguish this from skirmish creation."}}}]},{"id":"prepare-round","category":"battle","editions":["n26"],"title":{"ko":"N26 첫 전투 준비와 라운드","en":"N26 battle preparation and rounds"},"summary":{"ko":"크루, 전술, 배치, 우선권과 교대 활성화의 순서를 익힙니다.","en":"Learn crew preparation, tactics, deployment, priority, and alternating activations."},"minutes":15,"references":[{"kind":"coreRules","id":"n26-core-prebattle","edition":"n26"},{"kind":"coreRules","id":"n26-core-campaign-recovery","edition":"n26"},{"kind":"coreRules","id":"n26-core-terrain-definitions","edition":"n26"},{"kind":"coreRules","id":"n26-core-round-priority","edition":"n26"},{"kind":"coreRules","id":"n26-core-loadouts","edition":"n26"},{"kind":"coreRules","id":"n26-core-bottle-checks","edition":"n26"},{"kind":"coreRules","id":"n26-core-objectives","edition":"n26"},{"kind":"coreRules","id":"n26-core-activation-action-economy","edition":"n26"}],"steps":[{"id":"prebattle-order","title":{"ko":"전투 준비 순서","en":"Follow pre-battle order"},"body":{"ko":"도전과 영토 내기부터 정하고 시나리오, 전장, 크루, 전장 효과, 갱 전술, 배치 순으로 준비합니다. 시나리오의 크루 선정과 배치 조건을 먼저 확인하면 전술이나 지형 해석을 뒤늦게 바꾸는 일을 줄일 수 있습니다.","en":"Agree the challenge and territory stake, then resolve scenario, battlefield, crew, battlefield effects, gang tactics, and deployment. Checking crew and deployment conditions early keeps later tactics and terrain decisions consistent."},"bullets":[{"ko":"회복 대기 등 캠페인 상태로 참가할 수 없는 모델을 크루에서 제외합니다.","en":"Exclude models barred by campaign conditions such as Recovery."},{"ko":"지형의 성격과 선택 규칙은 시작 전에 상대와 합의합니다.","en":"Agree terrain definitions and optional rules before starting."}],"references":[{"kind":"coreRules","id":"n26-core-prebattle","edition":"n26"},{"kind":"coreRules","id":"n26-core-campaign-recovery","edition":"n26"},{"kind":"coreRules","id":"n26-core-terrain-definitions","edition":"n26"}]},{"id":"tactics","title":{"ko":"레이팅 차이와 전술","en":"Apply the Rating difference to tactics"},"body":{"ko":"기본 전술은 각 갱에 1개입니다. 레이팅이 낮은 갱은 차이 200크레딧마다 전술을 1개 추가로 받으며, 각 전술은 전투당 한 번 사용합니다. 실제 전술 카드의 발동 시점과 대상을 읽고 사용 여부를 표시하세요.","en":"Each gang receives 1 basic tactic. The lower-Rating gang receives 1 extra tactic for each 200-credit difference, and each tactic is used once per battle. Read the selected tactic’s timing and target, then track whether it has been used."},"bullets":[{"ko":"레이팅 비교에 사용할 명단과 시나리오의 예외를 함께 확인합니다.","en":"Check the roster used for Rating comparison and any scenario exception."},{"ko":"기본 전술과 추가 전술을 따로 기록하면 중복 지급을 피할 수 있습니다.","en":"Record basic and extra tactics separately to avoid duplicates."}],"references":[{"kind":"coreRules","id":"n26-core-prebattle","edition":"n26"}]},{"id":"priority","title":{"ko":"우선권 판정과 동점","en":"Resolve priority and ties"},"body":{"ko":"라운드는 우선권, 행동, 종료 단계로 진행합니다. 우선권 단계에 모델들을 준비 상태로 만들고 D6 대결을 합니다. 첫 라운드 동점은 재굴림하고 이후 동점은 직전 라운드에 우선권이 없던 쪽이 얻습니다.","en":"A round has priority, action, and end phases. Ready the models in the priority phase and roll opposed D6s. Reroll a tie in the first round; later ties go to the player who did not have priority in the previous round."},"bullets":[{"ko":"우선권은 갱 전체의 모델을 연속으로 모두 활성화하는 권리가 아닙니다.","en":"Priority does not mean activating your entire gang without interruption."},{"ko":"직전 라운드의 우선권 보유자를 표시해 두세요.","en":"Mark who held priority in the previous round."}],"references":[{"kind":"coreRules","id":"n26-core-round-priority","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"두 번째 라운드의 우선권 D6이 동점입니다. 첫 라운드에는 상대가 우선권을 가졌습니다. 누구의 우선권일까요?","en":"Priority is tied in round two. Your opponent had priority in round one. Who receives priority now?"},"options":[{"id":"1","text":{"ko":"항상 재굴림한다.","en":"Always reroll."}},{"id":"2","text":{"ko":"직전 라운드 우선권이 없던 나","en":"You, who lacked priority in the previous round"}},{"id":"3","text":{"ko":"직전 라운드 우선권을 가졌던 상대","en":"The opponent, who held priority previously"}}],"correctOption":"2","explanation":{"ko":"첫 라운드의 동점만 재굴림합니다. 이후 라운드의 동점은 이전 라운드에 우선권이 없던 쪽이 얻습니다.","en":"Only the first-round tie is rerolled. A later tie goes to the player without priority in the preceding round."}}},{"id":"alternate","title":{"ko":"준비 모델을 교대로 활성화","en":"Alternate ready models"},"body":{"ko":"우선권 보유자부터 준비된 모델 하나를 활성화하고 상대와 번갈아 진행합니다. 한 모델의 행동을 끝낸 뒤 다음 모델로 넘어갑니다. 그룹 활성화처럼 별도 규칙이 있는 경우에는 해당 절차를 적용합니다.","en":"Starting with the priority holder, players alternate activating one ready model. Finish that model’s actions before moving on. Apply a specific procedure when an exception such as Group Activation is used."},"bullets":[{"ko":"이미 활성화한 모델과 아직 준비된 모델을 마커로 구분합니다.","en":"Use markers to distinguish activated models from ready models."},{"ko":"같은 모델의 서로 다른 장비 세트는 추가 활성화 기회를 만들지 않습니다.","en":"A model’s different equipment cards do not grant extra activations."}],"references":[{"kind":"coreRules","id":"n26-core-round-priority","edition":"n26"},{"kind":"coreRules","id":"n26-core-loadouts","edition":"n26"}]},{"id":"endphase","title":{"ko":"종료 단계 순서","en":"Resolve the end phase in order"},"body":{"ko":"종료 단계에는 전투 이탈 체크, 승리·목표 확인, 지원군 순으로 처리합니다. 라운드 중 전투 이탈 원인이 발생했는지와 목표 주변의 상태를 확인하세요. 시나리오의 종료 조건을 만족하지 않았다면 다음 라운드를 준비합니다.","en":"Resolve Bottle checks, victory and objectives, then reinforcements. Check whether a Bottle trigger occurred and which models can affect objectives. If the scenario has not ended, prepare another round."},"bullets":[{"ko":"전투 이탈 체크는 해당 라운드의 OOA 발생 여부를 기준으로 합니다.","en":"Bottle checks depend on whether the gang suffered an OOA that round."},{"ko":"시나리오 자체의 승리 조건과 보상은 별도로 읽어야 합니다.","en":"Read the scenario’s own victory conditions and rewards."}],"references":[{"kind":"coreRules","id":"n26-core-bottle-checks","edition":"n26"},{"kind":"coreRules","id":"n26-core-objectives","edition":"n26"}]},{"id":"sequence-practice","title":{"ko":"첫 라운드 진행 연습","en":"Practice the first round"},"body":{"ko":"크루와 전술을 정하고 배치가 끝났습니다. 첫 우선권 대결이 동점이 났고 아직 아무 모델도 활성화하지 않았습니다. 어떤 순서로 행동 단계에 들어갈지 선택해 보세요.","en":"Crew, tactics, and deployment are complete. The first priority roll is tied, and no model has activated. Choose how to enter the action phase."},"bullets":[{"ko":"모든 행동을 먼저 확정하는 대신 각 행동을 끝내고 다음 행동을 선언합니다.","en":"Finish each action before declaring the next rather than precommitting every action."},{"ko":"시나리오에 특별 절차가 있으면 그 절차를 함께 적용합니다.","en":"Also apply any special scenario procedure."}],"references":[{"kind":"coreRules","id":"n26-core-round-priority","edition":"n26"},{"kind":"coreRules","id":"n26-core-activation-action-economy","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"첫 우선권 동점 뒤의 올바른 절차는?","en":"What follows a tie in the first priority roll?"},"options":[{"id":"1","text":{"ko":"방어자가 모든 모델을 먼저 활성화","en":"The defender activates every model first"}},{"id":"2","text":{"ko":"우선권 재굴림 → 승자부터 준비 모델 하나씩 교대 활성화","en":"Reroll priority → alternate one ready model starting with the winner"}},{"id":"3","text":{"ko":"즉시 종료 단계로 이동","en":"Skip straight to the end phase"}}],"correctOption":"2","explanation":{"ko":"첫 라운드 동점은 재굴림하고 우선권 보유자가 첫 활성화를 합니다. 이후 준비 모델을 하나씩 번갈아 활성화합니다.","en":"Reroll first-round priority ties. The priority holder activates first, then players alternate one ready model at a time."}}}]},{"id":"activation-states","category":"battle","editions":["n26"],"title":{"ko":"N26 행동 경제와 상태","en":"N26 actions and model states"},"summary":{"ko":"행동 비용, 중복 행동 금지, 제압·교전·중상과 그룹 활성화를 구분합니다.","en":"Understand action costs, repetition, Suppressed, Engaged, Seriously Injured, and Group Activation."},"minutes":18,"references":[{"kind":"coreRules","id":"n26-core-activation-action-economy","edition":"n26"},{"kind":"coreRules","id":"n26-core-exclusive-states","edition":"n26"},{"kind":"coreRules","id":"n26-core-conditions","edition":"n26"},{"kind":"coreRules","id":"n26-core-serious-suppression-markers","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-engaged-serious","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-group-interact-lastblow","edition":"n26"},{"kind":"coreRules","id":"n26-core-pets","edition":"n26"}],"steps":[{"id":"two-actions","title":{"ko":"행동 비용 세기","en":"Count action costs"},"body":{"ko":"기본 활성화에는 행동 2개가 있습니다. 싱글은 1개, 더블은 2개, 프리는 0개를 소모합니다. 먼저 한 행동을 완전히 해결한 뒤 다음 행동을 선언하세요. 프리 행동도 그것을 허용하는 규칙과 상황이 있어야 수행할 수 있습니다.","en":"A normal activation provides 2 actions. Single costs 1, Double costs 2, and Free costs 0. Resolve an action completely before declaring the next. A Free action still requires a rule and situation allowing it."},"bullets":[{"ko":"더블 행동을 선택하면 기본 행동 예산을 모두 사용합니다.","en":"A Double action uses the whole normal action budget."},{"ko":"같은 이름의 행동은 명시적 예외 없이는 한 활성화에 반복할 수 없습니다.","en":"The same named action cannot normally be repeated during an activation."}],"references":[{"kind":"coreRules","id":"n26-core-activation-action-economy","edition":"n26"}]},{"id":"state-priority","title":{"ko":"전투 상태 우선순위","en":"Apply state priority"},"body":{"ko":"액티브, 인게이지드, 서프레스드, 시리어슬리 인저드·대미지드는 상호 배타적인 전투 상태입니다. 충돌하면 중상·중손상, 교전, 제압, 활성 순으로 우선합니다. 이 상태와 캠페인의 회복 대기·사망 표시는 다르게 관리합니다.","en":"Active, Engaged, Suppressed, and Seriously Injured/Damaged are exclusive battle states. When they conflict, priority is Serious injury/damage, then Engaged, Suppressed, and Active. Keep these separate from campaign conditions such as Recovery and death."},"bullets":[{"ko":"조건은 여러 개가 겹칠 수 있으며 전투 상태와 별개입니다.","en":"Conditions can coexist and are distinct from the exclusive battle state."},{"ko":"탄약 부족은 모델 전체가 아니라 특정 무기 프로필에 적용될 수 있습니다.","en":"Out of Ammo can apply to a specific weapon profile rather than the whole model."}],"references":[{"kind":"coreRules","id":"n26-core-exclusive-states","edition":"n26"},{"kind":"coreRules","id":"n26-core-conditions","edition":"n26"}]},{"id":"action-choice","title":{"ko":"상태에 맞는 행동 선택","en":"Choose actions for the state"},"body":{"ko":"제압된 모델은 보통 행동 1개만 수행합니다. 교전 모델은 파이트 또는 리트리트 같은 교전 행동을 사용하고, 중상 모델은 크롤·회복 관련 행동·디스퍼릿 이스케이프를 검토합니다. 현재 상태가 행동의 적법성을 결정합니다.","en":"A Suppressed model normally performs only 1 action. Engaged models use engaged actions such as Fight or Retreat; Seriously Injured models consider Crawl, recovery-related actions, or Desperate Escape. The current state determines which actions are legal."},"bullets":[{"ko":"교전 상태에서 일반 이동을 선언해 접촉을 임의로 끊지 마세요.","en":"Do not use an ordinary Move to bypass an engaged state."},{"ko":"탈출 행동은 단순한 안전 이동이 아니라 OOA 처리를 동반합니다.","en":"Desperate Escape includes OOA resolution rather than a simple safe move."}],"references":[{"kind":"coreRules","id":"n26-core-serious-suppression-markers","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-engaged-serious","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"일반 액티브 전투원이 무브(싱글)를 마친 뒤, 예외 없이 다시 무브를 선언할 수 있을까요?","en":"Can a normal Active fighter perform Move (Single), then repeat Move without an exception?"},"options":[{"id":"1","text":{"ko":"남은 행동이 있으면 언제나 가능","en":"Always, while an action remains"}},{"id":"2","text":{"ko":"불가능. 같은 이름 행동 반복은 기본적으로 금지","en":"No. Repeating a named action is normally prohibited"}},{"id":"3","text":{"ko":"무브의 유형 이름만 바꾸면 가능","en":"Yes, if you rename its action type"}}],"correctOption":"2","explanation":{"ko":"행동 예산이 남는 것과 행동 반복이 허용되는 것은 별개입니다. 명시적 예외 없이 같은 이름의 행동을 반복할 수 없습니다.","en":"Having an action left does not itself permit repetition. A specific exception is needed to repeat the same named action."}}},{"id":"combat-actions","title":{"ko":"사격과 돌격의 비용","en":"Compare shooting and charging costs"},"body":{"ko":"슈트는 싱글이며 비헤비 원거리 무기를 사용합니다. 에임드 슈트는 더블로 명중 +1, 브레이스드 슈트는 더블로 헤비 무기를 사용합니다. 차지는 더블이고 성공하면 규칙이 허용하는 파이트 또는 라스트 블로를 프리로 수행합니다.","en":"Shoot is Single and uses a non-Heavy ranged weapon. Aimed Shoot is Double with +1 to hit; Braced Shoot is Double and uses Heavy weapons. Charge is Double, and a successful charge grants the allowed Free Fight or Last Blow."},"bullets":[{"ko":"더블 사격 뒤에 일반 무브를 추가할 기본 행동은 남지 않습니다.","en":"A Double shooting action leaves no ordinary action for Move."},{"ko":"차지 후 프리 전투는 추가 기본 행동을 얻은 것으로 계산하지 않습니다.","en":"A Free fight after charging does not add another ordinary action."}],"references":[{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"},{"kind":"coreRules","id":"n26-core-activation-action-economy","edition":"n26"}]},{"id":"group-actions","title":{"ko":"그룹 활성화와 상호작용","en":"Group Activation and interactions"},"body":{"ko":"그룹 활성화는 싱글입니다. 3인치 안의 준비된 아군 전투원을 선택하고 선택한 모델마다 리더십 -1을 적용한 체크를 합니다. 성공하면 자신의 활성화 뒤 선택한 전투원들을 순서대로 활성화합니다. 문 단말기 등은 인터랙트의 별도 대상 조건을 확인합니다.","en":"Group Activation is Single. Choose ready friendly fighters within 3 inches and make the Leadership check at −1 per selected fighter. On success, activate them in order after the acting model. For Interact, check the specific target conditions, such as a door terminal."},"bullets":[{"ko":"그룹 활성화를 다시 이어 붙이는 예외를 임의로 만들지 않습니다.","en":"Do not invent permission to chain further Group Activations."},{"ko":"차량·펫 등은 각자의 활성화 규칙도 확인합니다.","en":"Check separate activation rules for vehicles and Pets."}],"references":[{"kind":"coreRules","id":"n26-core-actions-group-interact-lastblow","edition":"n26"},{"kind":"coreRules","id":"n26-core-pets","edition":"n26"}]},{"id":"activation-practice","title":{"ko":"가상 활성화 계획","en":"Practice an activation plan"},"body":{"ko":"비헤비 총을 가진 액티브 전투원이 사격한 뒤 엄폐로 이동하려 합니다. 표적의 시야와 사거리를 확인했으며 이동 경로도 적법하다고 가정합니다. 기본 행동 예산 안에서 가능한 조합을 선택하세요.","en":"An Active fighter with a non-Heavy gun wants to shoot and then move into cover. Assume the target is visible and in range, and the movement path is legal. Select a combination within the normal action budget."},"bullets":[{"ko":"먼저 한 행동을 끝내고 다음 행동을 선언한다는 순서를 지킵니다.","en":"Keep the sequence of completing one action before declaring the next."},{"ko":"다른 조건이나 무기 특성이 행동을 제한하면 함께 적용합니다.","en":"Apply any additional condition or weapon trait that restricts actions."}],"references":[{"kind":"coreRules","id":"n26-core-activation-action-economy","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"어느 조합이 기본 행동 비용에 맞을까요?","en":"Which sequence fits the normal action costs?"},"options":[{"id":"1","text":{"ko":"에임드 슈트(더블) → 무브(싱글)","en":"Aimed Shoot (Double) → Move (Single)"}},{"id":"2","text":{"ko":"슈트(싱글) → 무브(싱글)","en":"Shoot (Single) → Move (Single)"}},{"id":"3","text":{"ko":"브레이스드 슈트(더블) → 런(더블)","en":"Braced Shoot (Double) → Run (Double)"}}],"correctOption":"2","explanation":{"ko":"슈트 1 + 무브 1 = 행동 2개입니다. 에임드 슈트와 브레이스드 슈트는 각각 더블이므로 기본 예산을 모두 씁니다.","en":"Shoot costs 1 and Move costs 1, totaling 2 actions. Aimed Shoot and Braced Shoot each use the full normal budget as Double actions."}}}]},{"id":"movement-terrain","category":"battle","editions":["n26"],"title":{"ko":"N26 이동과 지형 실습","en":"N26 movement and terrain practice"},"summary":{"ko":"거리, 적 접근, 어려운 지형, 등반·도약·추락을 계산합니다.","en":"Calculate distances, enemy exclusion, difficult terrain, climbing, leaping, and falls."},"minutes":20,"references":[{"kind":"coreRules","id":"n26-core-decisions-measurements","edition":"n26"},{"kind":"coreRules","id":"n26-core-movement-restrictions","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"},{"kind":"coreRules","id":"n26-core-mounted","edition":"n26"},{"kind":"coreRules","id":"n26-core-vehicle-movement-subtypes","edition":"n26"},{"kind":"coreRules","id":"n26-core-dexterity-difficult-dangerous","edition":"n26"},{"kind":"coreRules","id":"n26-core-climb-leap","edition":"n26"},{"kind":"coreRules","id":"n26-core-flying","edition":"n26"},{"kind":"coreRules","id":"n26-core-falling","edition":"n26"}],"steps":[{"id":"distance","title":{"ko":"이동 거리와 경로","en":"Measure the actual path"},"body":{"ko":"거리는 인치로 측정하며 높이 차이도 포함합니다. 일반 전투원 이동은 경로를 굽힐 수 있지만 차지·인게이지는 최단 경로를 사용합니다. 고형 지형이나 다른 모델을 통과할 수 없으며 이동 허용량을 전부 쓸 필요는 없습니다.","en":"Measure in inches, including height differences. Fighters can bend an ordinary movement path, while Charge and Engage use the shortest path. Do not pass through solid terrain or other models, and you need not use the full allowance."},"bullets":[{"ko":"기본 규칙의 사전 측정은 허용됩니다. 선택 규칙 채택 여부를 시작 전에 합의하세요.","en":"Premeasurement is allowed by default; agree any optional restriction before play."},{"ko":"보통 적 1인치 안에 들어갈 수 없고 차지·인게이지 등 명시된 예외를 적용합니다.","en":"Normally stay outside 1 inch of enemies, applying specific exceptions such as Charge and Engage."}],"references":[{"kind":"coreRules","id":"n26-core-decisions-measurements","edition":"n26"},{"kind":"coreRules","id":"n26-core-movement-restrictions","edition":"n26"}]},{"id":"distances","title":{"ko":"무브·런·차지 비교","en":"Compare Move, Run, and Charge"},"body":{"ko":"무브는 M, 런은 M+I, 차지는 M+D6, 인게이지는 D6인치입니다. 동일한 이동량이라도 행동 비용과 표적 조건은 다릅니다. 차량의 기본 이동은 전방 직선이며 이동 하위유형이 회전·지형 처리를 바꿀 수 있습니다.","en":"Move travels M, Run M+I, Charge M+D6, and Engage D6 inches. Similar distances can still have different action costs and target conditions. Vehicles normally move straight forward, with movement subtypes modifying turns and terrain handling."},"bullets":[{"ko":"차지와 런은 더블, 무브와 인게이지는 싱글입니다.","en":"Charge and Run are Double; Move and Engage are Single."},{"ko":"탑승 전투원은 일반 전투원과 다른 등반·회전 제한을 확인합니다.","en":"Mounted fighters have separate climbing and turning restrictions."}],"references":[{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"},{"kind":"coreRules","id":"n26-core-mounted","edition":"n26"},{"kind":"coreRules","id":"n26-core-vehicle-movement-subtypes","edition":"n26"}]},{"id":"difficult","title":{"ko":"어려운 지형 계산","en":"Calculate difficult terrain"},"body":{"ko":"전투원은 어려운 지형 1인치를 이동할 때 이동 허용량 2인치를 사용합니다. 위험 지형은 같은 이동 비용에 위험 굴림을 추가합니다. 위험 지형 통과 후 D6의 1은 자동 운드·세이브 불가 L1 명중을 일으킵니다.","en":"A fighter spends 2 inches of movement allowance per inch of difficult terrain. Dangerous terrain has the same cost plus a hazard roll. After crossing it, a D6 result of 1 causes an automatically wounding, no-save L1 hit."},"bullets":[{"ko":"지형을 통과하는 실제 거리와 소모되는 이동량을 구분하세요.","en":"Distinguish physical distance from movement allowance spent."},{"ko":"트랙드 등 차량 하위유형은 별도 지형 효과를 사용합니다.","en":"Vehicle subtypes such as Tracked have their own terrain effects."}],"references":[{"kind":"coreRules","id":"n26-core-dexterity-difficult-dangerous","edition":"n26"},{"kind":"coreRules","id":"n26-core-vehicle-movement-subtypes","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"M 5 전투원이 일반 지형 1인치 뒤 어려운 지형 2인치를 이동합니다. 소모 이동량은?","en":"An M 5 fighter moves 1 inch over ordinary terrain, then 2 inches through difficult terrain. How much allowance is spent?"},"options":[{"id":"1","text":{"ko":"3인치","en":"3 inches"}},{"id":"2","text":{"ko":"4인치","en":"4 inches"}},{"id":"3","text":{"ko":"5인치","en":"5 inches"}}],"correctOption":"3","explanation":{"ko":"일반 지형 1 + 어려운 지형 2×2 = 5인치를 사용합니다. 이 경로는 M 5 무브의 허용량을 모두 씁니다.","en":"1 ordinary + 2×2 difficult = 5 inches. That path uses the entire allowance of an M 5 Move."}}},{"id":"climb-leap","title":{"ko":"등반과 틈 도약","en":"Climb and cross gaps"},"body":{"ko":"일반 등반은 높이 1인치당 이동량 2인치이며 등반 중간에서 활성화를 끝낼 수 없습니다. 0.5인치 이하의 높이 차는 무료로 넘고 사다리·계단은 일반 등반의 두 배 비용을 쓰지 않습니다. 2인치 이하 틈은 자동 도약하며 더 넓으면 덱스테리티 판정이 필요합니다.","en":"Ordinary climbing costs 2 inches per inch of height, and an activation cannot end midway up a climb. Steps of at most 0.5 inch are crossed freely; ladders and stairs avoid the doubled climbing cost. Gaps of at most 2 inches are leapt automatically; wider gaps require Dexterity."},"bullets":[{"ko":"덱스테리티는 기본 D6 4+이며 자연 1은 실패, 6은 성공입니다.","en":"Dexterity normally succeeds on D6 4+, with natural 1 failing and 6 succeeding."},{"ko":"에셔는 덱스테리티에 +1을 받습니다.","en":"Escher receives +1 to Dexterity."},{"ko":"비행이나 워커 등에는 명시된 별도 이동 규칙을 적용합니다.","en":"Apply explicit movement rules for Flying, Walkers, and other exceptions."}],"references":[{"kind":"coreRules","id":"n26-core-climb-leap","edition":"n26"},{"kind":"coreRules","id":"n26-core-dexterity-difficult-dangerous","edition":"n26"},{"kind":"coreRules","id":"n26-core-flying","edition":"n26"}]},{"id":"falling","title":{"ko":"추락 위험 판단","en":"Understand fall consequences"},"body":{"ko":"추락 높이가 3인치 미만이면 제압, 3–6인치이면 제압과 자동 운드·세이브 불가 L1 명중, 6인치 초과면 OOA입니다. 자기 활성화 중 추락하면 그 활성화도 끝납니다. 자발적 하강은 덱스테리티 성공으로 효과 구간을 하나 낮출 수 있습니다.","en":"A fall under 3 inches causes Suppression; 3–6 inches causes Suppression plus an automatically wounding, no-save L1 hit; over 6 inches causes OOA. Falling during your activation also ends it. A successful Dexterity check for a voluntary jump down reduces the effect by one band."},"bullets":[{"ko":"난간으로 밀려났을 때는 덱스테리티로 추락 여부를 확인합니다.","en":"When pushed from an edge, resolve Dexterity to determine whether the model falls."},{"ko":"전투원에게 난간은 이 판정의 +1 보너스를 줍니다.","en":"A railing gives fighters +1 to that check."}],"references":[{"kind":"coreRules","id":"n26-core-falling","edition":"n26"}]},{"id":"movement-practice","title":{"ko":"경로 선택 연습","en":"Practice choosing a safe route"},"body":{"ko":"목표로 가는 짧은 길에는 4인치 낙차가 있고 긴 길에는 안전한 계단이 있습니다. 추락을 일반 이동처럼 처리하지 말고 높이·사용 행동·남은 이동량·목표 도착 위치를 함께 확인하세요.","en":"A short route to an objective has a 4-inch drop; a longer route uses safe stairs. Do not treat a fall as ordinary movement. Check height, action used, remaining allowance, and the final position together."},"bullets":[{"ko":"이 문제는 일반 추락의 효과 구간을 묻습니다. 비행이나 성공한 자발적 하강 예외는 적용하지 않습니다.","en":"This question uses an ordinary fall, without Flying or a successful voluntary-jump reduction."},{"ko":"실제 전장에서는 지형을 시작 전에 합의하고 측정하세요.","en":"Agree and measure terrain before the battle."}],"references":[{"kind":"coreRules","id":"n26-core-falling","edition":"n26"},{"kind":"coreRules","id":"n26-core-movement-restrictions","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"일반 전투원이 자기 활성화 중 4인치 추락했습니다. 기본 처리는?","en":"A normal fighter falls 4 inches during its activation. What is the base result?"},"options":[{"id":"1","text":{"ko":"제압만 받고 활성화를 계속한다.","en":"Only Suppressed, then continues activating."}},{"id":"2","text":{"ko":"제압 + 자동 운드·세이브 불가 L1 명중, 활성화 종료","en":"Suppressed + an automatically wounding no-save L1 hit; activation ends"}},{"id":"3","text":{"ko":"높이와 관계없이 즉시 사망한다.","en":"Immediately dies regardless of height."}}],"correctOption":"2","explanation":{"ko":"4인치는 3–6인치 구간입니다. 제압과 해당 명중을 해결하고 현재 활성화를 끝냅니다. OOA와 캠페인 사망도 서로 다른 처리입니다.","en":"4 inches is within the 3–6-inch band. Apply Suppression and the specified hit, then end the activation. OOA and campaign death are also separate outcomes."}}}]},{"id":"ranged-combat","category":"battle","editions":["n26"],"title":{"ko":"N26 사격과 탄약 실습","en":"N26 shooting and ammunition practice"},"summary":{"ko":"표적·사거리·명중·엄폐·운드·세이브와 속사의 처리 순서를 배웁니다.","en":"Learn targeting, range, hits, cover, wounds, saves, and Rapid Fire in order."},"minutes":22,"references":[{"kind":"coreRules","id":"n26-core-shooting","edition":"n26"},{"kind":"coreRules","id":"n26-core-los-arcs","edition":"n26"},{"kind":"coreRules","id":"n26-core-cover","edition":"n26"},{"kind":"coreRules","id":"n26-core-cover-save","edition":"n26"},{"kind":"coreRules","id":"n26-core-wound-target","edition":"n26"},{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"},{"kind":"coreRules","id":"n26-core-invulnerable-save","edition":"n26"},{"kind":"coreRules","id":"n26-core-ammo-rapid-fire","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-reload-treat-repair-sabotage","edition":"n26"},{"kind":"coreRules","id":"n26-core-blast-template-optional-shooting","edition":"n26"},{"kind":"coreRules","id":"n26-core-wounds-and-lethality","edition":"n26"}],"steps":[{"id":"target","title":{"ko":"표적과 무기 프로필 선언","en":"Declare a target and weapon profile"},"body":{"ko":"사용할 무기 프로필과 시야 안의 표적을 정하고 거리를 측정한 뒤 BS 명중 테스트를 합니다. 기본 시야는 360도지만 아크 특성이 있으면 지정 아크를 적용합니다. 사거리 밖의 공격은 실패합니다.","en":"Choose the weapon profile and a target in line of sight, measure range, then make the BS hit test. Vision is normally 360 degrees, while an Arc trait restricts the relevant weapon. An out-of-range attack fails."},"bullets":[{"ko":"시야선은 몸체로 확인하며 베이스·총열·장식만 보이는 것으로 충분하다고 가정하지 않습니다.","en":"Trace line of sight using the body; do not assume the base, gun barrel, or decorations alone suffice."},{"ko":"거리·특성·표적 상태에 따른 수정을 확인한 뒤 굴립니다.","en":"Check range, traits, and target-state modifiers before rolling."}],"references":[{"kind":"coreRules","id":"n26-core-shooting","edition":"n26"},{"kind":"coreRules","id":"n26-core-los-arcs","edition":"n26"}]},{"id":"hit-cover","title":{"ko":"명중과 엄폐 구분","en":"Separate hitting from cover saves"},"body":{"ko":"BS 테스트에서 자연 1은 실패, 자연 6은 성공입니다. 중상 표적에는 명중 -1이 적용됩니다. 표적의 몸체가 지형이나 모델에 가려지면 엄폐이며, N26 원거리 엄폐는 단거리 세이브 +1, 장거리 세이브 +2로 적용합니다.","en":"A natural 1 misses and natural 6 hits on the BS test. A Seriously Injured target imposes −1 to hit. A partially obscured body has cover; N26 ranged cover gives +1 to the save at short range and +2 at long range."},"bullets":[{"ko":"베이스나 장식만 가려진 것은 엄폐가 아닙니다.","en":"Obscuring only the base or decorations does not provide cover."},{"ko":"이 수업의 엄폐 보너스를 다른 판본의 명중 수정으로 바꿔 쓰지 마세요.","en":"Do not replace this lesson’s cover save bonus with a different edition’s hit modifier."},{"ko":"보통 명중한 모델은 제압됩니다.","en":"A hit model is normally Suppressed."}],"references":[{"kind":"coreRules","id":"n26-core-shooting","edition":"n26"},{"kind":"coreRules","id":"n26-core-cover","edition":"n26"},{"kind":"coreRules","id":"n26-core-cover-save","edition":"n26"}]},{"id":"wound","title":{"ko":"S와 T로 운드 목표 찾기","en":"Find the wound target from S and T"},"body":{"ko":"명중한 뒤에는 S와 T를 비교해 운드 D6 목표를 정합니다. S가 T의 두 배 이상이면 2+, 더 크면 3+, 같으면 4+, 더 작지만 절반 초과면 5+, 절반 이하면 6+입니다. 서로 다른 무기나 표적은 필요한 값을 분리하세요.","en":"After a hit, compare S with T to find the wound D6 target: 2+ at least double; 3+ greater; 4+ equal; 5+ lower but above half; 6+ at most half. Separate attacks with different weapons or targets."},"bullets":[{"ko":"명중 성공이 자동 운드를 뜻하지는 않습니다.","en":"A hit does not automatically cause a wound."},{"ko":"자동 운드 같은 명시된 특성이 있으면 그 예외를 적용합니다.","en":"Apply explicit exceptions such as automatic wounds."}],"references":[{"kind":"coreRules","id":"n26-core-wound-target","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"S 4 공격이 T 3 표적에 명중했습니다. 운드 목표는?","en":"An S 4 attack hits a T 3 target. What is the wound target?"},"options":[{"id":"1","text":{"ko":"2+","en":"2+"}},{"id":"2","text":{"ko":"3+","en":"3+"}},{"id":"3","text":{"ko":"4+","en":"4+"}}],"correctOption":"2","explanation":{"ko":"S 4는 T 3보다 크지만 두 배인 6에는 못 미칩니다. 따라서 운드 목표는 3+입니다.","en":"S 4 exceeds T 3 but is below double T (6), so the wound target is 3+."}}},{"id":"save","title":{"ko":"AP와 세이브 계산","en":"Apply AP and saves"},"body":{"ko":"성공 운드마다 사용할 세이브를 하나 선택하고 D6에 AP와 적용 가능한 수정을 반영해 Sv 이상인지 확인합니다. 자연 1·2는 실패합니다. 무적 세이브는 AP와 엄폐를 포함한 모든 수정을 무시하고, 세이브 금지를 다른 세이브로 우회할 수 없습니다.","en":"For each successful wound, choose one save and compare D6 plus AP and applicable modifiers to Sv. Natural 1 and 2 fail. An invulnerable save ignores all modifiers, including AP and cover. A prohibition on saves cannot be bypassed by choosing another save."},"bullets":[{"ko":"여러 종류의 세이브가 있어도 성공 운드마다 한 번만 선택해 굴립니다.","en":"Even with multiple save types, choose and roll only one per wound."},{"ko":"예: Sv 4+, AP -1, 단거리 엄폐 +1이면 수정 합은 0입니다.","en":"Example: Sv 4+, AP −1, short-range cover +1 gives a net modifier of 0."}],"references":[{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"},{"kind":"coreRules","id":"n26-core-invulnerable-save","edition":"n26"},{"kind":"coreRules","id":"n26-core-cover-save","edition":"n26"}]},{"id":"ammo","title":{"ko":"탄약과 래피드 파이어","en":"Resolve ammunition and Rapid Fire"},"body":{"ko":"탄약 부족은 사용한 무기 프로필에 적용되며 리로드 싱글로 선택 프로필 하나를 회복합니다. 래피드 파이어(X)는 사용할 화력 주사위를 최대 X개까지 정합니다. 탄약 기호 1개는 탄약 부족, 2개 이상은 그 전투에서 사용 불가를 일으킵니다.","en":"Out of Ammo applies to the profile used; Reload (Single) restores one chosen profile. Rapid Fire (X) allows choosing up to X Firepower dice. One Ammo symbol causes Out of Ammo; two or more disable the weapon for that battle."},"bullets":[{"ko":"애모 테스트 실패는 추가 화력 주사위가 아니라 추가 탄약 기호 1개로 처리합니다.","en":"A failed Ammo test adds one Ammo symbol, not another Firepower die."},{"ko":"명중 분배는 운드 굴림 전에 정하며 원표적 주변의 거리와 조건을 확인합니다.","en":"Allocate split hits before wound rolls, checking distance and conditions around the original target."},{"ko":"폭발·템플릿이 교전에 맞으면 같은 교전의 아군도 맞을 수 있습니다.","en":"Blasts and templates hitting an engagement can also hit friendly participants."}],"references":[{"kind":"coreRules","id":"n26-core-ammo-rapid-fire","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-reload-treat-repair-sabotage","edition":"n26"},{"kind":"coreRules","id":"n26-core-blast-template-optional-shooting","edition":"n26"}]},{"id":"ranged-practice","title":{"ko":"사격 전체 순서 연습","en":"Practice the complete shooting sequence"},"body":{"ko":"슈트를 선언한 전투원이 적법한 표적에 명중했습니다. 이제 공격의 S와 표적 T를 비교하고, 운드가 성공하면 표적이 AP와 엄폐를 적용한 세이브를 합니다. 막지 못하면 W를 줄이고 필요할 때 부상 주사위로 넘어갑니다.","en":"A fighter declares Shoot and hits a legal target. Compare attack S with target T; a successful wound is followed by the target’s save using AP and cover. An unsaved wound reduces W, proceeding to injury dice when required."},"bullets":[{"ko":"표적 선언 → 거리 → 명중 → 운드 → 세이브 → W·부상 순서를 체크리스트로 사용하세요.","en":"Use target → range → hit → wound → save → W/injury as a checklist."},{"ko":"탄약과 특성의 별도 발동 시점도 놓치지 마세요.","en":"Track separate ammunition and trait timing as well."}],"references":[{"kind":"coreRules","id":"n26-core-shooting","edition":"n26"},{"kind":"coreRules","id":"n26-core-wound-target","edition":"n26"},{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"},{"kind":"coreRules","id":"n26-core-wounds-and-lethality","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"성공 운드에 대해 Sv 4+, AP -1, 장거리 엄폐 +2이고 자연 D6이 3입니다. 일반 세이브 결과는?","en":"For a successful wound, Sv is 4+, AP −1, long-range cover +2, and the natural D6 is 3. What is the normal save result?"},"options":[{"id":"1","text":{"ko":"3 - 1 + 2 = 4이므로 성공","en":"3 − 1 + 2 = 4, so success"}},{"id":"2","text":{"ko":"AP가 있으면 항상 실패","en":"Any AP causes automatic failure"}},{"id":"3","text":{"ko":"엄폐는 항상 명중에만 적용되어 실패","en":"Cover only ever modifies hitting, so failure"}}],"correctOption":"1","explanation":{"ko":"수정 결과 4가 Sv 4+를 만족합니다. 자연 주사위는 3이므로 자연 1·2 자동 실패에도 해당하지 않습니다.","en":"The modified result is 4, meeting Sv 4+. The natural die is 3, so the natural 1–2 automatic failure does not apply."}}}]},{"id":"close-combat","category":"battle","editions":["n26"],"title":{"ko":"N26 돌격과 근접전 실습","en":"N26 charging and close-combat practice"},"summary":{"ko":"교전, 주·보조무기, 공격 수, 이니셔티브와 정리 이동을 배웁니다.","en":"Learn engagement, primary/offhand weapons, attack counts, Initiative, and consolidation."},"minutes":20,"references":[{"kind":"coreRules","id":"n26-core-engagement","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"},{"kind":"coreRules","id":"n26-core-unseen-melee","edition":"n26"},{"kind":"coreRules","id":"n26-core-melee-start","edition":"n26"},{"kind":"coreRules","id":"n26-core-mounted","edition":"n26"},{"kind":"coreRules","id":"n26-core-initiative-order","edition":"n26"},{"kind":"coreRules","id":"n26-core-melee-hit-tests","edition":"n26"},{"kind":"coreRules","id":"n26-core-assists-interference","edition":"n26"},{"kind":"coreRules","id":"n26-core-wound-target","edition":"n26"},{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"},{"kind":"coreRules","id":"n26-core-consolidation","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-group-interact-lastblow","edition":"n26"}],"steps":[{"id":"charge-engage","title":{"ko":"접근과 교전 시작","en":"Approach and become engaged"},"body":{"ko":"전투원끼리는 중상이 아닌 적과 베이스가 닿으면 교전합니다. 차지는 M+D6인치의 더블, 인게이지는 D6인치의 싱글이며 성공 뒤 규칙에 맞는 프리 파이트 또는 라스트 블로를 수행합니다. 일반 이동으로 적 접근 제한을 우회하지 마세요.","en":"Fighters become engaged on base contact with an enemy that is not Seriously Injured. Charge is Double at M+D6 inches; Engage is Single at D6 inches. Success allows the appropriate Free Fight or Last Blow. Ordinary movement does not bypass enemy exclusion."},"bullets":[{"ko":"차지·인게이지 선언 때 보이지 않았던 상대에게는 근접 명중 -1입니다.","en":"Melee attacks against an opponent unseen when Charge/Engage was declared suffer −1 to hit."},{"ko":"중상 표적에 대한 접근과 라스트 블로는 별도 조건을 확인합니다.","en":"Check separate approach and Last Blow conditions for Seriously Injured targets."}],"references":[{"kind":"coreRules","id":"n26-core-engagement","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-active-combat-movement","edition":"n26"},{"kind":"coreRules","id":"n26-core-unseen-melee","edition":"n26"}]},{"id":"weapons-attacks","title":{"ko":"무기 선택과 공격 수","en":"Choose weapons and count attacks"},"body":{"ko":"활성 모델은 주무기 하나와 허용되는 보조무기 하나를 고릅니다. 활성 주무기 공격은 A에 이번 활성화의 차지 보너스 1을 더하고, 보조무기는 1회입니다. 비활성 참가자는 A와 무관하게 주무기로 1회 공격합니다. 라이트 무기는 최대 1회 공격합니다.","en":"The active model chooses a primary weapon and an allowed offhand weapon. Primary attacks use A plus 1 when the model charged this activation; the offhand gets 1 attack. A non-active participant makes 1 primary attack regardless of A. Light weapons attack at most once."},"bullets":[{"ko":"활성 모델과 비활성 모델의 공격 수를 같은 방식으로 계산하지 않습니다.","en":"Calculate active and non-active attacks differently."},{"ko":"탑승 전투원 등은 보조무기 사용 제한도 확인합니다.","en":"Check restrictions on offhand weapons, including Mounted fighters."}],"references":[{"kind":"coreRules","id":"n26-core-melee-start","edition":"n26"},{"kind":"coreRules","id":"n26-core-mounted","edition":"n26"}]},{"id":"initiative","title":{"ko":"공격 순서와 동률","en":"Order attacks by Initiative"},"body":{"ko":"공격 순서는 수정 I가 높은 쪽부터입니다. 이번 활성화에 차지가 성공했다면 순서 결정용 I에 +2를 받습니다. 동률은 동시 공격이므로 편의상 한쪽을 먼저 굴려도 동률 상대는 그 공격으로 OOA나 중상이 되어도 공격합니다.","en":"Resolve attacks from highest modified I downward. A successful charge in this activation adds +2 I for ordering attacks. Ties are simultaneous: rolling one side first for convenience does not prevent the tied opponent’s attacks even if it becomes OOA or Seriously Injured."},"bullets":[{"ko":"차지의 공격 수 +1과 순서 결정용 I +2는 서로 다른 보너스입니다.","en":"The charge bonus of +1 attack and ordering bonus of +2 I are separate."},{"ko":"언윌디 등 무기 특성의 순서 수정도 확인하세요.","en":"Also check ordering effects such as Unwieldy."}],"references":[{"kind":"coreRules","id":"n26-core-initiative-order","edition":"n26"},{"kind":"coreRules","id":"n26-core-melee-start","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"A의 기본 I는 3이고 이번에 차지했습니다. B의 수정 없는 I는 5입니다. 특성이 없다면 공격 순서는?","en":"A has base I 3 and charged this activation. B has unmodified I 5. With no other traits, what is the attack order?"},"options":[{"id":"1","text":{"ko":"A의 I는 5가 되어 동시 공격","en":"A reaches I 5, so attacks are simultaneous"}},{"id":"2","text":{"ko":"차지한 A는 언제나 동률을 무시하고 먼저","en":"Charging A always ignores ties and attacks first"}},{"id":"3","text":{"ko":"B가 I 5이므로 항상 A보다 먼저","en":"B always attacks before A because B has I 5"}}],"correctOption":"1","explanation":{"ko":"A는 3 + 2 = 5로 B와 동률입니다. 동률 공격은 동시로 처리하며 먼저 굴린 공격 때문에 다른 쪽 공격을 취소하지 않습니다.","en":"A has 3 + 2 = 5, tying B. The attacks are simultaneous; resolving one first does not cancel the other side’s tied attacks."}}},{"id":"hits-support","title":{"ko":"WS 명중과 지원·방해","en":"Resolve WS, assistance, and interference"},"body":{"ko":"근접 명중은 WS 테스트로 처리하며 자연 1은 실패, 자연 6은 성공입니다. 적법한 지원은 +1, 방해는 -1이고 같은 종류는 여러 모델이 있어도 중첩하지 않습니다. 무기·표적별로 다른 공격은 나누어 해결하세요.","en":"Melee hit tests use WS, with natural 1 failing and natural 6 succeeding. Qualifying assistance gives +1 and interference −1; multiple models do not stack the same modifier. Resolve different weapons and targets separately."},"bullets":[{"ko":"지원자는 대상과 교전하면서 다른 같은 적 갱 모델과는 교전하지 않는 등 조건을 만족해야 합니다.","en":"An assistant must meet conditions such as engaging the target without engaging another model of that enemy gang."},{"ko":"명중 이후 운드·세이브·부상 절차는 공격 프로필에 따라 적용합니다.","en":"After hitting, apply wounds, saves, and injuries using the attack profile."}],"references":[{"kind":"coreRules","id":"n26-core-melee-hit-tests","edition":"n26"},{"kind":"coreRules","id":"n26-core-assists-interference","edition":"n26"},{"kind":"coreRules","id":"n26-core-wound-target","edition":"n26"},{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"}]},{"id":"after-fight","title":{"ko":"정리 이동과 라스트 블로","en":"Consolidate or resolve Last Blow"},"body":{"ko":"활성 모델과 교전하던 적 전부가 OOA·중상·중손상이 되면 I인치 정리 이동이 가능합니다. 이동 중 적 1인치 안을 지나더라도 종료는 모든 적에서 최소 1인치 밖이어야 합니다. 라스트 블로는 1인치 내 중상 적과 D6+S 대결을 하여 동점 이상이면 OOA로 만듭니다.","en":"If all enemies engaged with the active model become OOA or Seriously Injured/Damaged, it may consolidate I inches. It can enter within 1 inch during the move but must finish at least 1 inch from every enemy. Last Blow contests D6+S against a Seriously Injured enemy within 1 inch, causing OOA on a tie or better."},"bullets":[{"ko":"중상 적이 남았다는 이유만으로 자동 사망 처리하지 마세요.","en":"Do not treat a remaining Seriously Injured enemy as automatically dead."},{"ko":"정리 이동의 종료 거리와 목표 통제 위치를 함께 확인합니다.","en":"Check the consolidation endpoint against both enemy distance and objective position."}],"references":[{"kind":"coreRules","id":"n26-core-consolidation","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-group-interact-lastblow","edition":"n26"}]},{"id":"melee-practice","title":{"ko":"공격 수 계산 연습","en":"Practice counting melee attacks"},"body":{"ko":"A 2 전투원이 이번 활성화에 차지했고, 라이트가 아닌 주무기와 적법한 보조무기를 선택했습니다. 상대는 비활성 참가자입니다. 무기 특성 등 다른 수정은 없다고 가정하고 공격 수를 계산하세요.","en":"An A 2 fighter charged this activation and selected a non-Light primary weapon plus a legal offhand. Its opponent is non-active. Assume no other trait or modifier and calculate attacks."},"bullets":[{"ko":"주무기와 보조무기의 명중·S·AP·L이 다르면 주사위를 구분합니다.","en":"Keep dice separate when primary and offhand hit, S, AP, or L differ."},{"ko":"상대의 A가 높아도 비활성 참가자의 기본 공격 수는 별도 규칙입니다.","en":"A non-active participant uses its own attack-count rule even with a high A value."}],"references":[{"kind":"coreRules","id":"n26-core-melee-start","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"활성 전투원의 기본 공격 수는?","en":"How many attacks does the active fighter make?"},"options":[{"id":"1","text":{"ko":"주무기 2 + 보조무기 2","en":"Primary 2 + offhand 2"}},{"id":"2","text":{"ko":"주무기 3 + 보조무기 1","en":"Primary 3 + offhand 1"}},{"id":"3","text":{"ko":"주무기 4, 보조무기는 없음","en":"Primary 4, no offhand"}}],"correctOption":"2","explanation":{"ko":"주무기는 A 2 + 차지 1 = 3회, 허용 보조무기는 1회입니다. 라이트·언윌디 같은 특성이나 유형 제한이 있으면 별도로 적용합니다.","en":"Primary attacks are A 2 + 1 for charging = 3; the legal offhand makes 1. Apply any Light, Unwieldy, or type restriction separately."}}}]},{"id":"wounds-recovery","category":"battle","editions":["n26"],"title":{"ko":"N26 운드·부상·회복","en":"N26 Wounds, injuries, and recovery"},"summary":{"ko":"L과 W, 부상 결과, 치료 지원, 지속 부상과 캠페인 회복을 구분합니다.","en":"Distinguish L and W, injury results, recovery assistance, lasting injuries, and campaign Recovery."},"minutes":22,"references":[{"kind":"coreRules","id":"n26-core-wounds-and-lethality","edition":"n26"},{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"},{"kind":"coreRules","id":"n26-core-injury-dice-results","edition":"n26"},{"kind":"coreRules","id":"n26-core-injured-intoxicated-webbed","edition":"n26"},{"kind":"coreRules","id":"n26-core-lasting-effects","edition":"n26"},{"kind":"coreRules","id":"n26-core-recovery","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-reload-treat-repair-sabotage","edition":"n26"},{"kind":"coreRules","id":"n26-core-campaign-recovery","edition":"n26"},{"kind":"coreRules","id":"n26-core-dice-types","edition":"n26"}],"steps":[{"id":"wounds-lethality","title":{"ko":"W 손실과 L의 역할","en":"Apply W loss and L"},"body":{"ko":"막지 못한 운드마다 W를 1 줄이고 W는 0 아래로 내려가지 않습니다. W가 0에 도달하거나 이미 0인 모델이 추가 피해를 받으면 L개 부상 주사위를 굴리고 결과 하나를 선택합니다. L은 한 번에 잃는 W 수가 아닙니다.","en":"Each unsaved wound removes 1 W, to a minimum of 0. When W reaches zero, or a model already at zero takes further damage, roll L injury dice and select one result. L is not the number of W lost from a single unsaved wound."},"bullets":[{"ko":"한 발이 명중했다는 것과 운드가 성공했다는 것, W가 줄었다는 것은 각각 다른 단계입니다.","en":"A hit, a successful wound, and lost W are separate steps."},{"ko":"동시에 들어온 서로 다른 공격의 처리 순서는 피격 모델 플레이어가 정합니다.","en":"The defender chooses the order of simultaneous incoming attacks."}],"references":[{"kind":"coreRules","id":"n26-core-wounds-and-lethality","edition":"n26"},{"kind":"coreRules","id":"n26-core-save-roll","edition":"n26"}]},{"id":"injury-results","title":{"ko":"부상 결과와 OOA","en":"Interpret injury results"},"body":{"ko":"부상 주사위는 인저드·대미지드, 시리어슬리 인저드·대미지드, 아웃 오브 액션을 구분합니다. 중상 결과를 이미 중상인 모델에게 다시 적용해도 자체 추가 효과는 없습니다. OOA는 전장에서 제거하는 것이며 곧바로 캠페인 사망을 뜻하지 않습니다.","en":"Injury dice distinguish Injured/Damaged, Seriously Injured/Damaged, and Out of Action. A repeated Seriously Injured result has no extra effect by itself. OOA removes the model from the battlefield; it does not automatically mean campaign death."},"bullets":[{"ko":"OOA 뒤에는 필요한 지속 부상·손상 처리를 별도로 합니다.","en":"Resolve lasting injuries or damage separately after OOA when required."},{"ko":"W가 0인 인저드·대미지드 모델은 스킬 사용 제한도 확인합니다.","en":"Check skill restrictions for an Injured/Damaged model at W 0."}],"references":[{"kind":"coreRules","id":"n26-core-injury-dice-results","edition":"n26"},{"kind":"coreRules","id":"n26-core-injured-intoxicated-webbed","edition":"n26"},{"kind":"coreRules","id":"n26-core-lasting-effects","edition":"n26"}]},{"id":"injury-practice","title":{"ko":"부상 주사위 선택 연습","en":"Practice selecting an injury result"},"body":{"ko":"W 1 모델이 L 2 공격에서 막지 못한 운드 하나를 받았습니다. 먼저 W를 0으로 만든 뒤 부상 주사위를 굴립니다. 여러 주사위의 결과를 전부 누적하는지, 하나를 고르는지 확인하세요.","en":"A W 1 model suffers one unsaved wound from an L 2 attack. First reduce W to zero, then roll injury dice. Decide whether multiple dice all apply or one result is selected."},"bullets":[{"ko":"L 2라고 W를 두 번 빼거나 결과 두 개를 모두 적용하지 않습니다.","en":"L 2 does not remove W twice or apply both injury results."},{"ko":"모델의 현재 상태와 부상 결과를 각각 기록합니다.","en":"Track the current model state separately from the injury result."}],"references":[{"kind":"coreRules","id":"n26-core-wounds-and-lethality","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"이 상황에서 기본 처리는?","en":"What is the base resolution here?"},"options":[{"id":"1","text":{"ko":"W를 -1로 낮추고 부상 주사위 없음","en":"Reduce W to −1 and roll no injury dice"}},{"id":"2","text":{"ko":"W 0, 부상 주사위 2개 중 결과 하나 선택","en":"W 0; roll 2 injury dice and choose one result"}},{"id":"3","text":{"ko":"W 0, 부상 주사위 2개 결과 모두 강제 적용","en":"W 0; apply both injury dice results"}}],"correctOption":"2","explanation":{"ko":"운드 하나는 W 1을 줄이고 0 아래로 내려가지 않습니다. L 2에 따라 부상 주사위 두 개를 굴린 뒤 하나만 선택합니다.","en":"One unsaved wound removes 1 W, never below zero. L 2 gives two injury dice, from which one result is selected."}}},{"id":"recovery-assist","title":{"ko":"전투 중 회복과 지원","en":"Recover during battle with assistance"},"body":{"ko":"활성화를 중상·중손상으로 시작한 모델은 활성화 끝에 회복합니다. 1인치 안의 적이 중상·중손상이 아니면 굴림 없이 OOA입니다. 적법한 정상 아군 전투원 하나가 1인치 내에서 지원하면 회복 주사위 +1을 받으며 여러 개면 결과 하나를 고릅니다.","en":"A model that started its activation Seriously Injured/Damaged recovers at the end. An enemy within 1 inch that is not Seriously Injured/Damaged causes OOA without rolling. One eligible friendly fighter within 1 inch grants +1 recovery die; select one result when rolling multiple dice."},"bullets":[{"ko":"비스트와 차량은 회복 지원을 할 수 없습니다.","en":"Beasts and vehicles cannot provide recovery assistance."},{"ko":"차량은 회복 지원을 받을 수도 없습니다.","en":"Vehicles also cannot receive recovery assistance."},{"ko":"트리트 앨라이·리페어는 적법한 대상에게 즉시 회복 테스트를 주는 별도 싱글 행동입니다.","en":"Treat Ally/Repair are separate Single actions granting an immediate recovery test to an eligible target."}],"references":[{"kind":"coreRules","id":"n26-core-recovery","edition":"n26"},{"kind":"coreRules","id":"n26-core-actions-reload-treat-repair-sabotage","edition":"n26"}]},{"id":"lasting-recovery","title":{"ko":"지속 부상과 캠페인 회복","en":"Resolve lasting injuries and campaign Recovery"},"body":{"ko":"캠페인에서는 OOA 사건마다 상대가 D66 지속 부상·손상 표를 굴립니다. 한 사건에 OOA 원인이 겹쳐도 표는 한 번입니다. 캠페인의 리커버리는 해당 사이클의 이후 전투와 포스트 사이클 행동을 막으며 명부 업데이트에서 해제합니다.","en":"In a campaign, the opponent rolls D66 for a lasting injury/damage after each OOA event. Multiple simultaneous causes still produce one table roll for the event. Campaign Recovery prevents later battles and post-cycle actions in that cycle and clears during roster updating."},"bullets":[{"ko":"D66은 첫 D6을 십의 자리, 다음 D6을 일의 자리로 읽습니다.","en":"Read D66 using the first D6 as tens and the next as units."},{"ko":"스커미시에서는 지속 부상 처리를 생략할 수 있습니다.","en":"Lasting injuries may be omitted in skirmishes."},{"ko":"앱에서 중상·리커버리·킬 파이터·삭제를 같은 작업으로 취급하지 마세요.","en":"Do not treat Serious injury, Recovery, Kill Fighter, and Delete as the same app action."}],"references":[{"kind":"coreRules","id":"n26-core-lasting-effects","edition":"n26"},{"kind":"coreRules","id":"n26-core-campaign-recovery","edition":"n26"},{"kind":"coreRules","id":"n26-core-dice-types","edition":"n26"}]},{"id":"recovery-practice","title":{"ko":"가상 구조 상황","en":"Practice a recovery decision"},"body":{"ko":"중상 전투원의 1인치 안에 액티브 적이 있고, 아군이 회복을 지원하려 합니다. 적의 근접 위험은 회복 주사위를 추가하는 것만으로 무시되지 않습니다. 회복 판정 전에 먼저 자동 OOA 조건을 확인하세요.","en":"An Active enemy is within 1 inch of a Seriously Injured fighter, and a friendly model wants to assist recovery. Adding a recovery die does not ignore the nearby enemy rule. Check automatic OOA conditions before rolling."},"bullets":[{"ko":"치료와 회복 모두 적법한 대상·거리·상태부터 확인합니다.","en":"Before treatment or recovery, check target eligibility, distance, and state."},{"ko":"훈련용 선택은 실제 파이터의 상태를 변경하지 않습니다.","en":"This practice choice does not change a real fighter’s status."}],"references":[{"kind":"coreRules","id":"n26-core-recovery","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"회복 시 1인치 안에 중상이 아닌 적이 있으면?","en":"What happens at recovery with a non-Seriously Injured enemy within 1 inch?"},"options":[{"id":"1","text":{"ko":"아군이 있으면 적을 무시하고 회복","en":"Ignore the enemy if a friendly model is present"}},{"id":"2","text":{"ko":"추가 주사위 둘로 회복","en":"Recover with two extra dice"}},{"id":"3","text":{"ko":"굴림 없이 OOA","en":"OOA without a roll"}}],"correctOption":"3","explanation":{"ko":"이 거리의 적은 회복 굴림 자체를 막고 OOA를 발생시킵니다. 정상적인 지원 보너스로 이 조건을 우회하지 않습니다.","en":"The nearby enemy prevents the recovery roll and causes OOA. Ordinary assistance does not bypass that condition."}}}]},{"id":"morale-objectives","category":"battle","editions":["n26"],"title":{"ko":"N26 신경·이탈·목표","en":"N26 Nerve, Bottle, and objectives"},"summary":{"ko":"클 체크, 전투 이탈, 자발적 포기, 목표 통제와 XP를 익힙니다.","en":"Learn Cool checks, Bottle, voluntary fleeing, objective control, and XP."},"minutes":18,"references":[{"kind":"coreRules","id":"n26-core-dice-resolution","edition":"n26"},{"kind":"coreRules","id":"n26-core-stats","edition":"n26"},{"kind":"coreRules","id":"n26-core-nerve-check","edition":"n26"},{"kind":"coreRules","id":"n26-core-leaders-champions-loners","edition":"n26"},{"kind":"coreRules","id":"n26-core-bottle-checks","edition":"n26"},{"kind":"coreRules","id":"n26-core-succumb","edition":"n26"},{"kind":"coreRules","id":"n26-core-voluntary-flee","edition":"n26"},{"kind":"coreRules","id":"n26-core-objectives","edition":"n26"},{"kind":"coreRules","id":"n26-core-xp-events","edition":"n26"}],"steps":[{"id":"tests-checks","title":{"ko":"테스트와 체크 구분","en":"Distinguish tests from checks"},"body":{"ko":"테스트는 결과가 목표 이상이면 성공하고 체크는 목표 이하이면 성공합니다. WS·BS는 D6 테스트, 정신 능력치는 2D6 체크를 사용합니다. 재굴림은 같은 주사위에 한 번만 가능하며 새 결과를 적용합니다.","en":"A test succeeds at or above its target; a check succeeds at or below it. WS/BS use D6 tests, while mental characteristics use 2D6 checks. A die can be rerolled only once and the new result must be used."},"bullets":[{"ko":"능력치가 높아지는 것과 목표 숫자가 좋아지는 방향을 구분합니다.","en":"Distinguish increasing a characteristic from improving a target number."},{"ko":"자연 결과에 대한 명시적 예외는 해당 규칙에서 확인합니다.","en":"Read the relevant rule for explicit natural-result exceptions."}],"references":[{"kind":"coreRules","id":"n26-core-dice-resolution","edition":"n26"},{"kind":"coreRules","id":"n26-core-stats","edition":"n26"}]},{"id":"nerve","title":{"ko":"근처 아군의 OOA와 신경 체크","en":"Resolve Nerve after a nearby OOA"},"body":{"ko":"아군이 3인치 안에서 OOA가 되면 쿨 체크를 하고 실패한 관찰 모델은 제압됩니다. 시야 안의 리더·챔피언은 자신의 쿨을 쓰게 하는 범위가 있으므로 해당 모델과 거리를 확인합니다.","en":"When a friendly model becomes OOA within 3 inches, take a Cool check; a failing observing model becomes Suppressed. A visible Leader or Champion can allow use of its Cool within its own range, so check the model and distance."},"bullets":[{"ko":"챔피언의 신경용 쿨 범위는 6인치, 리더는 12인치입니다.","en":"Champion Cool support for Nerve reaches 6 inches; Leader support reaches 12 inches."},{"ko":"시야·유형·상태에 따른 적법성을 먼저 확인하세요.","en":"Check visibility, type, and state eligibility first."}],"references":[{"kind":"coreRules","id":"n26-core-nerve-check","edition":"n26"},{"kind":"coreRules","id":"n26-core-leaders-champions-loners","edition":"n26"}]},{"id":"bottle","title":{"ko":"전투 이탈 체크의 발동","en":"Check when Bottle is triggered"},"body":{"ko":"자기 갱이 이번 라운드에 OOA를 한 명 이상 냈을 때 종료 단계에서 전장 최고 적격 리더십으로 전투 이탈 체크를 합니다. 실패하면 모델 한 명을 철수시키고 자연 12면 두 명입니다. 비교전 아군이 남아 있으면 교전 모델부터 선택할 수 없습니다.","en":"If the gang suffered at least one OOA this round, make a Bottle check in the end phase using its highest eligible Leadership on the battlefield. Failure withdraws one model; natural 12 withdraws two. An engaged model cannot be chosen first while unengaged friendlies remain."},"bullets":[{"ko":"이전 라운드 OOA만으로 이번 라운드 발동을 자동 가정하지 않습니다.","en":"Do not assume a previous round’s OOA alone triggers the check now."},{"ko":"중상·중손상 상태로 철수한 모델은 별도 서컴 판정도 확인합니다.","en":"A withdrawn Seriously Injured/Damaged model also needs the separate Succumb procedure."}],"references":[{"kind":"coreRules","id":"n26-core-bottle-checks","edition":"n26"},{"kind":"coreRules","id":"n26-core-succumb","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"이번 라운드 OOA가 없고 이전 라운드에만 있었습니다. 기본 발동 조건만 보면 이번 종료 단계의 전투 이탈 체크는?","en":"The gang had no OOA this round, only in the previous round. Under the basic trigger, does it check Bottle now?"},"options":[{"id":"1","text":{"ko":"이번 라운드 OOA 조건이 없으므로 발동하지 않는다.","en":"No, because this round had no OOA trigger."}},{"id":"2","text":{"ko":"한 번 OOA가 나면 매 라운드 자동 발동한다.","en":"Yes, one OOA triggers it automatically every later round."}},{"id":"3","text":{"ko":"모델 수가 줄면 항상 D6으로 굴린다.","en":"Always roll a D6 whenever the roster is smaller."}}],"correctOption":"1","explanation":{"ko":"기본 발동은 이번 라운드의 자갱 OOA 발생입니다. 별도 시나리오나 특수규칙이 있으면 그것도 적용하세요.","en":"The base trigger is a gang model becoming OOA during this round. Apply any separate scenario or special rule as well."}}},{"id":"voluntary","title":{"ko":"자발적 전투 포기와 굴복","en":"Choose voluntary fleeing and Succumb"},"body":{"ko":"시작 크루의 3분의 1을 올림한 수 이상이 OOA 또는 철수하면 승리 확인 시작에 자발적 전투 포기가 가능합니다. 전원 제거와 자동 패배를 적용합니다. 전투 종료 시 중상·중손상인 모델은 D6의 3+면 생존, 1–2면 OOA 후 지속 부상·손상을 처리합니다.","en":"Once at least the rounded-up third of the starting crew is OOA or withdrawn, the gang may voluntarily flee at the start of the victory check. Remove the gang and apply automatic defeat. At battle end, a Seriously Injured/Damaged model survives Succumb on D6 3+; 1–2 causes OOA and lasting injury/damage."},"bullets":[{"ko":"시작 크루 7명이면 자발적 포기 기준은 3명입니다.","en":"With a starting crew of 7, the voluntary fleeing threshold is 3."},{"ko":"중상 상태로 철수한 모델도 서컴 대상입니다.","en":"Models withdrawn while Seriously Injured also require Succumb."}],"references":[{"kind":"coreRules","id":"n26-core-voluntary-flee","edition":"n26"},{"kind":"coreRules","id":"n26-core-succumb","edition":"n26"}]},{"id":"control","title":{"ko":"목표 통제 조건","en":"Check objective control"},"body":{"ko":"목표 중심 3인치 안에 펫이 아닌 아군 전투원이 있고 적 모델이 없어야 통제합니다. 중상·중손상 모델은 무시합니다. 차량과 펫은 통제할 수 없지만 적의 통제를 방해할 수 있으므로 단순히 모델 수를 비교하지 마세요.","en":"Control requires a friendly non-Pet fighter within 3 inches of the objective center and no enemy model there. Ignore Seriously Injured/Damaged models. Vehicles and Pets cannot control, but can contest, so control is not a simple comparison of model counts."},"bullets":[{"ko":"목표 XP는 통제 전투원 중 플레이어가 고른 한 명에게 줍니다.","en":"Choose one controlling fighter to receive the objective XP."},{"ko":"목표 XP는 전투원별로 전투당 한 번이며 차량·펫은 받을 수 없습니다.","en":"Objective XP is once per fighter per battle and unavailable to vehicles or Pets."}],"references":[{"kind":"coreRules","id":"n26-core-objectives","edition":"n26"},{"kind":"coreRules","id":"n26-core-xp-events","edition":"n26"}]},{"id":"objective-practice","title":{"ko":"목표 점령 실습","en":"Practice objective control"},"body":{"ko":"아군 정상 갱어와 적 정상 펫이 모두 목표 중심 3인치 안에 있습니다. 적 전투원은 없고, 목표를 통제할 수 있는 아군 전투원은 있습니다. 펫이 통제하지 못한다는 말이 방해도 못한다는 뜻인지 구분하세요.","en":"A friendly healthy Ganger and an enemy healthy Pet are both within 3 inches of an objective. There is no enemy fighter, and your Ganger is able to control. Distinguish inability to control from inability to contest."},"bullets":[{"ko":"목표 주변의 각 모델을 아군·적, 유형, 상태로 나누어 확인합니다.","en":"Check each nearby model’s side, type, and state."},{"ko":"시나리오가 다른 목표 규칙을 명시하면 그 조건을 따릅니다.","en":"Apply different objective conditions when the scenario explicitly provides them."}],"references":[{"kind":"coreRules","id":"n26-core-objectives","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"이 경우 아군이 목표를 통제할까요?","en":"Does the friendly gang control the objective?"},"options":[{"id":"1","text":{"ko":"예. 펫은 목표에 아무 영향이 없다.","en":"Yes. Pets have no effect on objectives."}},{"id":"2","text":{"ko":"아니요. 적 펫이 통제를 방해한다.","en":"No. The enemy Pet contests it."}},{"id":"3","text":{"ko":"양쪽 모델 수가 같으므로 각각 XP를 얻는다.","en":"Both receive XP because model counts are equal."}}],"correctOption":"2","explanation":{"ko":"펫은 목표를 통제할 수 없지만 방해할 수 있습니다. 적 펫이 적법한 범위 안에 있으므로 아군은 이 목표를 통제하지 못합니다.","en":"Pets cannot control objectives but can contest them. The enemy Pet in range prevents the friendly gang from controlling this objective."}}}]},{"id":"postbattle-cycle","category":"campaign","editions":["n26"],"title":{"ko":"N26 전투 후와 사이클 정산","en":"N26 post-battle and post-cycle management"},"summary":{"ko":"전투 결과, XP, 장비 회수, 포스트 사이클 행동·수입·정리를 기록합니다.","en":"Record results, XP, recovered equipment, post-cycle actions, income, and cleanup."},"minutes":24,"references":[{"kind":"coreRules","id":"n26-core-post-battle-sequence","edition":"n26"},{"kind":"coreRules","id":"n26-core-territory-reallocation","edition":"n26"},{"kind":"coreRules","id":"n26-core-report-results","edition":"n26"},{"kind":"coreRules","id":"n26-core-xp-events","edition":"n26"},{"kind":"coreRules","id":"n26-core-rewards","edition":"n26"},{"kind":"coreRules","id":"n26-core-dead-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-types-roster-removal","edition":"n26"},{"kind":"coreRules","id":"n26-core-post-cycle-sequence","edition":"n26"},{"kind":"coreRules","id":"n26-core-work-territory","edition":"n26"},{"kind":"coreRules","id":"n26-core-train","edition":"n26"},{"kind":"coreRules","id":"n26-core-medical-escort","edition":"n26"},{"kind":"coreRules","id":"n26-core-bionics-installation","edition":"n26"},{"kind":"coreRules","id":"n26-core-develop-tactics","edition":"n26"},{"kind":"coreRules","id":"n26-core-visit-trading-post","edition":"n26"},{"kind":"coreRules","id":"n26-core-collect-income","edition":"n26"},{"kind":"coreRules","id":"n26-core-post-cycle-cleanup","edition":"n26"},{"kind":"coreRules","id":"n26-core-redistribute-equipment","edition":"n26"}],"steps":[{"id":"postbattle-order","title":{"ko":"전투 직후 순서","en":"Resolve the immediate post-battle sequence"},"body":{"ko":"두 플레이어가 함께 마무리, 영토 재배정, 보상 획득, 정리, 결과 보고 순서로 처리합니다. 전투 후 처리와 사이클 종료 처리는 다른 시퀀스입니다. 전투 한 번마다 포스트 사이클 전체를 자동 수행하지 마세요.","en":"Both players resolve wrap-up, territory reallocation, rewards, cleanup, and reporting together. Post-battle and post-cycle are separate sequences. Do not automatically run the full post-cycle sequence after every battle."},"bullets":[{"ko":"내기 영토는 승자에게 가며 무승부는 기존 소유·미점유 상태를 유지합니다.","en":"The winner gains the staked territory; a draw preserves existing ownership or vacancy."},{"ko":"결과 보고에는 참가 갱·승패·획득 영토·각 갱이 만든 적 OOA를 포함합니다.","en":"Report participating gangs, outcome, territory gained, and enemy OOA caused by each gang."}],"references":[{"kind":"coreRules","id":"n26-core-post-battle-sequence","edition":"n26"},{"kind":"coreRules","id":"n26-core-territory-reallocation","edition":"n26"},{"kind":"coreRules","id":"n26-core-report-results","edition":"n26"}]},{"id":"xp-events","title":{"ko":"경험치 중복 없이 기록","en":"Record XP without duplicates"},"body":{"ko":"전투 참가 +1 XP, 자기 행동으로 적 직접 중상 +1 또는 직접 OOA +2 XP입니다. 대상이 리더·챔피언·브루트·차량이면 +1을 추가합니다. 같은 활성화의 같은 적에게 중상과 OOA 보상을 중복해 더하지 않습니다.","en":"Participation grants +1 XP; directly causing Serious injury with your action grants +1, or directly causing OOA grants +2. Add +1 for a Leader, Champion, Brute, or Vehicle target. Do not add both the Serious injury and OOA awards for the same enemy in the same activation."},"bullets":[{"ko":"적법한 회복 지원 성공과 목표 통제의 XP도 별도 조건을 확인합니다.","en":"Check separate conditions for successful recovery assistance and objective XP."},{"ko":"앱의 XP 추가에 사건과 이유를 남기면 상대와 검증하기 쉽습니다.","en":"Record the event and reason in Add XP to make verification easier."}],"references":[{"kind":"coreRules","id":"n26-core-xp-events","edition":"n26"}]},{"id":"rewards-equipment","title":{"ko":"보상과 사망 장비 회수","en":"Handle rewards and dead fighters’ equipment"},"body":{"ko":"장비 보상은 보관고에 넣고 포스트 사이클에 분배합니다. 전투 종료에 자기 갱 모델이 전장에 남아 있으면 사망 전투원 장비를 회수할 수 있으나 유형별 소지품 소멸 예외도 확인합니다. 명성은 증가를 먼저 적용하고 감소시키며 최저 1입니다.","en":"Put equipment rewards in the stash for distribution during post-cycle. A gang model remaining on the battlefield at the end allows recovery of dead fighters’ equipment, subject to subtype exceptions that remove equipment. Apply Reputation increases before decreases, to a minimum of 1."},"bullets":[{"ko":"차량·브루트·행어온의 명부 제거와 소지품 규칙은 별도로 확인합니다.","en":"Check specific roster-removal equipment rules for Vehicles, Brutes, and Hangers-on."},{"ko":"장비 회수 가능과 실제 사망 확정은 서로 다른 판단입니다.","en":"Equipment recovery eligibility and confirmed death are separate decisions."}],"references":[{"kind":"coreRules","id":"n26-core-rewards","edition":"n26"},{"kind":"coreRules","id":"n26-core-dead-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-types-roster-removal","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"같은 활성화에 같은 일반 적을 직접 중상으로 만든 뒤 OOA로 만들었습니다. 이 두 사건의 기본 XP는?","en":"In the same activation, you directly cause Serious injury and then OOA to the same ordinary enemy. What is the base XP for those two events?"},"options":[{"id":"1","text":{"ko":"1 + 2 = 3 XP","en":"1 + 2 = 3 XP"}},{"id":"2","text":{"ko":"OOA 보상 2 XP만 적용","en":"Apply the OOA award of 2 XP"}},{"id":"3","text":{"ko":"OOA는 XP를 주지 않는다.","en":"OOA grants no XP."}}],"correctOption":"2","explanation":{"ko":"같은 활성화·같은 적의 중상과 OOA 보상은 중복되지 않습니다. 이 문항은 참가 XP와 특정 대상 보너스를 제외한 두 사건의 보상만 묻습니다.","en":"Do not duplicate Serious injury and OOA awards for the same enemy in one activation. This question excludes participation XP and special target bonuses."}}},{"id":"cycle-actions","title":{"ko":"포스트 사이클 행동 배정","en":"Assign post-cycle actions"},"body":{"ko":"포스트 사이클은 행동, 수입 수집, 명부 업데이트 순서입니다. 리커버리·크리티컬이 아닌 모델은 각각 행동 하나를 수행합니다. 영토 작업은 적격 모델 최대 5명이 각각 15크레딧, 훈련은 행동 가능한 모델에게 2 XP를 줍니다.","en":"Post-cycle resolves actions, income collection, then roster updating. Each model not in Recovery or Critical performs one action. Work Territory allows up to 5 eligible models, earning 15 credits each; Train grants 2 XP to an eligible model."},"bullets":[{"ko":"영토 작업은 리더·챔피언·갱어·프로스펙트가 수행합니다.","en":"Leaders, Champions, Gangers, and Prospects can Work Territory."},{"ko":"같은 모델에 영토 작업과 훈련 등 행동을 중복 배정하지 마세요.","en":"Do not assign both Work Territory and Train, or other duplicate actions, to one model."},{"ko":"의료 호송·바이오닉·전술 개발·교역소 방문은 수행자와 비용을 따로 확인합니다.","en":"Check actor and cost requirements for Medical Escort, Bionics, Develop Tactics, and Visit Trading Post."}],"references":[{"kind":"coreRules","id":"n26-core-post-cycle-sequence","edition":"n26"},{"kind":"coreRules","id":"n26-core-work-territory","edition":"n26"},{"kind":"coreRules","id":"n26-core-train","edition":"n26"},{"kind":"coreRules","id":"n26-core-medical-escort","edition":"n26"},{"kind":"coreRules","id":"n26-core-bionics-installation","edition":"n26"},{"kind":"coreRules","id":"n26-core-develop-tactics","edition":"n26"},{"kind":"coreRules","id":"n26-core-visit-trading-post","edition":"n26"}]},{"id":"income-update","title":{"ko":"수입과 명부 업데이트","en":"Collect income and update the roster"},"body":{"ko":"영토 수입·보너스에 명성 1당 10크레딧을 더합니다. 명부 업데이트는 승급, 교역소 방문, 장비 재분배, 정리 순으로 진행합니다. 리커버리를 해제하고 사망·파괴·은퇴한 모델을 정리하되, 소지품 처리부터 확인하세요.","en":"Add 10 credits per Reputation to territory income and boons. Roster updating proceeds through advancements, trading, equipment redistribution, and cleanup. Clear Recovery and remove dead, destroyed, or retired models after checking their equipment handling."},"bullets":[{"ko":"포스트 사이클 행동 전에 리커버리를 미리 지워 행동 자격을 주지 마세요.","en":"Do not clear Recovery early to make a model eligible for a post-cycle action."},{"ko":"영토 작업 수입과 영토 자체 수입은 서로 다른 항목입니다.","en":"Work Territory earnings and territory income are separate entries."}],"references":[{"kind":"coreRules","id":"n26-core-collect-income","edition":"n26"},{"kind":"coreRules","id":"n26-core-post-cycle-sequence","edition":"n26"},{"kind":"coreRules","id":"n26-core-post-cycle-cleanup","edition":"n26"},{"kind":"coreRules","id":"n26-core-redistribute-equipment","edition":"n26"}]},{"id":"cycle-practice","title":{"ko":"가상 사이클 장부","en":"Practice a cycle ledger"},"body":{"ko":"적격 모델 4명이 영토 작업을 하고 명성은 3, 영토 자체 수입과 보너스는 합계 40크레딧이라고 가정합니다. 다른 수입과 지출은 없습니다. 각각의 원인을 구분하여 총 수입을 계산하세요.","en":"Assume 4 eligible models Work Territory, Reputation is 3, and territory income plus boons totals 40 credits. There are no other earnings or costs. Keep each source distinct and calculate total income."},"bullets":[{"ko":"연습 장부: 영토 작업 + 영토 수입·보너스 + 명성 수입입니다.","en":"Practice ledger: Work Territory + territory income/boons + Reputation income."},{"ko":"실제 정산에서는 치료비·구매비 등 지출도 별도로 기록합니다.","en":"In a real cycle, separately record costs such as treatment and purchases."}],"references":[{"kind":"coreRules","id":"n26-core-work-territory","edition":"n26"},{"kind":"coreRules","id":"n26-core-collect-income","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"총 수입은 얼마일까요?","en":"What is the total income?"},"options":[{"id":"1","text":{"ko":"70크레딧","en":"70 credits"}},{"id":"2","text":{"ko":"100크레딧","en":"100 credits"}},{"id":"3","text":{"ko":"130크레딧","en":"130 credits"}}],"correctOption":"3","explanation":{"ko":"영토 작업 4×15 = 60, 명성 3×10 = 30, 영토 수입 40이므로 합계 130크레딧입니다.","en":"Work Territory is 4×15 = 60; Reputation adds 3×10 = 30; territory income is 40, totaling 130 credits."}}}]},{"id":"growth-special-rules","category":"campaign","editions":["n26"],"title":{"ko":"N26 성장·거래·특수규칙 읽기","en":"N26 advancement, trade, and special-rule literacy"},"summary":{"ko":"누적 XP, 승급, 교역, 조건과 워드 예외를 안전하게 해석합니다.","en":"Interpret cumulative XP, promotions, trade, conditions, and Wyrd exceptions carefully."},"minutes":24,"references":[{"kind":"coreRules","id":"n26-core-advancement-timing","edition":"n26"},{"kind":"coreRules","id":"n26-core-xp-bands","edition":"n26"},{"kind":"coreRules","id":"n26-core-advancement-table","edition":"n26"},{"kind":"coreRules","id":"n26-core-ganger-promotion","edition":"n26"},{"kind":"coreRules","id":"n26-core-prospect-promotion","edition":"n26"},{"kind":"coreRules","id":"n26-core-specialist","edition":"n26"},{"kind":"coreRules","id":"n26-core-buy-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-sell-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-redistribute-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-visit-trading-post","edition":"n26"},{"kind":"coreRules","id":"n26-core-type-semantics","edition":"n26"},{"kind":"coreRules","id":"n26-core-conditions","edition":"n26"},{"kind":"coreRules","id":"n26-core-wyrd-perils-triggers","edition":"n26"},{"kind":"coreRules","id":"n26-core-wyrd-weapon-ammo","edition":"n26"},{"kind":"coreRules","id":"n26-core-dice-types","edition":"n26"}],"steps":[{"id":"cumulative-xp","title":{"ko":"누적 XP와 성장 구간","en":"Track cumulative XP and bands"},"body":{"ko":"N26 성장은 XP를 소비해 구매하지 않습니다. 포스트 사이클에 누적 XP가 새로운 구간에 들어가면 그 구간의 성장을 처리합니다. 6에서 7 XP가 되는 것은 새 구간 진입의 예입니다. 시작 XP는 성장 보상을 자동 발생시키지 않습니다.","en":"N26 does not purchase advancements by spending XP. During post-cycle, entering a new cumulative XP band grants its advancement. Moving from 6 to 7 XP is an example. Starting XP does not automatically trigger an advancement."},"bullets":[{"ko":"구간의 등급명이 같아도 서로 다른 행이면 별도 구간입니다.","en":"Bands are separate rows even when their rank labels match."},{"ko":"0 XP의 첫 성장이나 표 결과 선택 방향처럼 확인이 필요한 항목은 확정해 가르치지 않습니다.","en":"Do not assume unresolved details such as the first advancement from 0 XP or cross-row result selection."},{"ko":"성장으로 늘어나는 크레딧 가치를 함께 기록합니다.","en":"Record the credit value added by an advancement."}],"references":[{"kind":"coreRules","id":"n26-core-advancement-timing","edition":"n26"},{"kind":"coreRules","id":"n26-core-xp-bands","edition":"n26"},{"kind":"coreRules","id":"n26-core-advancement-table","edition":"n26"}]},{"id":"promotion","title":{"ko":"성장과 역할 승급 구분","en":"Separate advancement from promotion"},"body":{"ko":"갱어는 포스트 사이클에 누적 XP 37 이상이면 성장 굴림 뒤 갱어를 챔피언으로 바꿉니다. 프로스펙트는 누적 XP 13 이상에서 성장 굴림 대신 갱어·스페셜리스트를 얻고 프로스펙트를 잃으며, 가치가 15크레딧 증가합니다.","en":"At 37 or more cumulative XP in post-cycle, a Ganger becomes a Champion after its advancement roll. At 13 or more XP, a Prospect promotes instead of rolling, gaining Ganger and Specialist, losing Prospect, and increasing value by 15 credits."},"bullets":[{"ko":"명명된 원래 유형과 다른 하위유형은 유지합니다.","en":"Keep the original named type and other subtypes."},{"ko":"프로스펙트는 전문분야 하나와 해당 무료 스킬 하나를 정합니다.","en":"A Prospect selects one specialisation and its associated free skill."},{"ko":"확인되지 않은 전문분야 대응을 임의로 만들어 주지 않습니다.","en":"Do not invent unverified specialisation-to-skill mappings."}],"references":[{"kind":"coreRules","id":"n26-core-ganger-promotion","edition":"n26"},{"kind":"coreRules","id":"n26-core-prospect-promotion","edition":"n26"},{"kind":"coreRules","id":"n26-core-specialist","edition":"n26"}]},{"id":"advancement-practice","title":{"ko":"성장 해석 연습","en":"Practice interpreting advancement"},"body":{"ko":"누적 XP가 6이던 갱어가 전투 후 XP 1을 얻어 7이 되었습니다. XP를 다시 0으로 낮추거나 비용처럼 차감하는 대신 새 구간과 처리 시점을 확인하세요. 실제 성장 표 결과와 값 증가는 별도로 기록합니다.","en":"A Ganger at cumulative XP 6 gains 1 XP after a battle, reaching 7. Instead of resetting XP or treating it as a cost, check the new band and timing. Record the actual advancement result and added value separately."},"bullets":[{"ko":"이 문항에서는 성장 조건만 확인하며 실제 성장 주사위를 굴리거나 파이터를 수정하지 않습니다.","en":"This question checks eligibility only; it rolls no real advancement and changes no fighter."},{"ko":"같은 구간을 반복 적용하지 않도록 이전 성장 기록을 확인합니다.","en":"Check prior advancement records to avoid granting the same band twice."}],"references":[{"kind":"coreRules","id":"n26-core-advancement-timing","edition":"n26"},{"kind":"coreRules","id":"n26-core-xp-bands","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"이 상황의 올바른 N26 해석은?","en":"Which N26 interpretation is correct?"},"options":[{"id":"1","text":{"ko":"XP를 소비해 0으로 낮추고 즉시 성장 구매","en":"Spend XP down to 0 and immediately buy an advancement"}},{"id":"2","text":{"ko":"누적 XP 7을 유지하고 포스트 사이클에 새 구간 성장 처리","en":"Keep cumulative XP 7 and resolve the new band in post-cycle"}},{"id":"3","text":{"ko":"갱어는 37 XP까지 어떤 성장도 없다.","en":"Gangers cannot advance at all until 37 XP."}}],"correctOption":"2","explanation":{"ko":"N26은 누적 XP를 유지합니다. 6→7은 새 구간 진입이며 포스트 사이클 성장 대상입니다. 갱어의 챔피언 승급 기준과 일반 성장은 별개입니다.","en":"N26 retains cumulative XP. The move from 6 to 7 enters a new band for post-cycle advancement. Ordinary advancement and the Ganger-to-Champion promotion threshold are different rules."}}},{"id":"trade","title":{"ko":"구매·판매와 장비 접근","en":"Buy, sell, and check equipment access"},"body":{"ko":"갱 장비 목록은 항상 구매 가능하지만 외부 교역소 접근에는 교역소 방문 행동이 필요합니다. 거래마다 크레딧과 TP를 모두 소모하고 남은 TP는 교역 단계 끝에 사라집니다. E 독점 장비는 해당 모델 목록에 있어야 합니다.","en":"The gang equipment list is always available, while external trading requires a Visit Trading Post action. Each purchase spends credits and TP, and unused TP expires at the end of the trading substep. Exclusive E equipment must appear on the model’s list."},"bullets":[{"ko":"보관고 장비는 제거하고 가치 절반, 최소 5크레딧에 판매합니다.","en":"Selling stash equipment removes it and earns half its value, minimum 5 credits."},{"ko":"홀수 가격의 판매 반올림과 TP 생성 산식은 확인 전 임의로 확정하지 않습니다.","en":"Do not assume unresolved odd-price sale rounding or TP generation formulas."},{"ko":"지급·재분배 때 받는 모델의 장비 제한도 다시 확인합니다.","en":"When transferring equipment, check the recipient’s restrictions again."}],"references":[{"kind":"coreRules","id":"n26-core-buy-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-sell-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-redistribute-equipment","edition":"n26"},{"kind":"coreRules","id":"n26-core-visit-trading-post","edition":"n26"}]},{"id":"special-rules","title":{"ko":"예외를 읽는 순서","en":"Read special-rule exceptions"},"body":{"ko":"특수규칙은 적용 판본, 대상 유형, 발동 시점, 거리·시야, 비용, 효과, 종료 조건 순으로 읽으면 놓치기 쉽지 않습니다. 워드처럼 별도 판정이 있는 능력은 일반 사격이나 스킬로 단순화하지 마세요. 자연 2·12의 역류와 발현 성공 여부도 분리해 처리합니다.","en":"Read a special rule by edition, eligible type, timing, range/visibility, cost, effect, and ending condition. An ability with its own tests, such as Wyrd, cannot be reduced to ordinary shooting or a generic skill. Separate Perils on natural 2/12 from whether manifestation succeeds."},"bullets":[{"ko":"워드 발현 자연 2는 자동 발현 후 역류, 자연 12는 자동 실패 후 역류입니다.","en":"Manifestation on natural 2 automatically succeeds then causes Perils; natural 12 automatically fails then causes Perils."},{"ko":"워드가 만드는 무기는 탄약 부족이 되지 않으며 화력 주사위 탄약 기호를 무시합니다.","en":"Weapons created by Wyrd powers cannot run Out of Ammo and ignore Firepower Ammo symbols."},{"ko":"앱의 규칙 라이브러리에서 해당 판본의 원 항목과 특성을 함께 확인합니다.","en":"Use the rules library to inspect the matching-edition entry and its traits."}],"references":[{"kind":"coreRules","id":"n26-core-type-semantics","edition":"n26"},{"kind":"coreRules","id":"n26-core-conditions","edition":"n26"},{"kind":"coreRules","id":"n26-core-wyrd-perils-triggers","edition":"n26"},{"kind":"coreRules","id":"n26-core-wyrd-weapon-ammo","edition":"n26"}]},{"id":"reading-practice","title":{"ko":"모호한 항목 다루기","en":"Practice handling uncertain entries"},"body":{"ko":"모든 데이터가 자동 판정 가능한 것은 아닙니다. 상세 규칙에서 확인이 필요하다고 표시한 항목은 확정 수치를 새로 만들어 적용하지 말고 아비트레이터와 합의해 기록하세요. 이 학습 과정도 확인된 판본 데이터와 연습용 예시를 구분합니다.","en":"Not every entry can be automated conclusively. If a detailed rule marks an interpretation unresolved, do not invent a definitive value. Agree a ruling with the arbitrator and record it. This curriculum also distinguishes verified edition data from practice examples."},"bullets":[{"ko":"갱·시나리오·장비의 명시적 예외는 기본 규칙과 함께 읽습니다.","en":"Read explicit gang, scenario, and equipment exceptions alongside the core rule."},{"ko":"판정에 쓴 값과 이유를 메모하면 이후 동일 상황에 일관되게 적용할 수 있습니다.","en":"Recording the chosen value and reason supports consistency in later games."},{"ko":"다른 판본의 익숙한 규칙으로 빈칸을 자동 채우지 않습니다.","en":"Do not automatically fill gaps with a familiar rule from another edition."}],"references":[{"kind":"coreRules","id":"n26-core-visit-trading-post","edition":"n26"},{"kind":"coreRules","id":"n26-core-advancement-table","edition":"n26"},{"kind":"coreRules","id":"n26-core-dice-types","edition":"n26"}],"exercise":{"type":"choice","prompt":{"ko":"TP 생성 방식이 확인 필요로 표시되어 있습니다. 가장 적절한 대응은?","en":"The TP generation formula is marked unresolved. What is the most appropriate response?"},"options":[{"id":"1","text":{"ko":"다른 판본 수치를 가져와 자동 확정","en":"Import another edition’s value as definitive"}},{"id":"2","text":{"ko":"가능한 값 중 가장 큰 수를 적용","en":"Choose the largest possible value"}},{"id":"3","text":{"ko":"확인된 접근 규칙은 적용하고 산식은 아비트레이터와 합의해 기록","en":"Apply verified access rules, then agree and record the formula with the arbitrator"}}],"correctOption":"3","explanation":{"ko":"확인된 부분과 모호한 부분을 구분해야 합니다. 판본이 다른 수치나 추측을 확정 규칙처럼 적용하지 말고 캠페인의 합의를 남기세요.","en":"Separate established rules from unresolved interpretation. Avoid presenting another edition’s value or a guess as definitive; record the campaign ruling."}}}]}];
globalThis.UK_TUTORIALS=lessons;
})();
